package com.matbakhy.orders.internal;

import com.matbakhy.availability.api.SlotInventory;
import com.matbakhy.availability.api.SlotInventory.Reservation;
import com.matbakhy.catalog.api.MealCatalog;
import com.matbakhy.cooks.api.KitchenDirectory;
import com.matbakhy.cooks.api.KitchenDirectory.FulfillmentContact;
import com.matbakhy.identity.api.AddressDirectory;
import com.matbakhy.identity.api.AddressDirectory.OwnedAddress;
import com.matbakhy.identity.api.CheckoutContactPolicy;
import com.matbakhy.identity.api.CheckoutContactPolicy.VerifiedContact;
import com.matbakhy.orders.api.OrderCases;
import com.matbakhy.orders.api.QuoteDirectory;
import com.matbakhy.orders.api.QuoteDirectory.QuotedItem;
import com.matbakhy.orders.api.QuoteDirectory.ValidQuote;
import com.matbakhy.shared.error.ApiException;
import com.matbakhy.shared.error.ApiException.FieldError;
import com.matbakhy.shared.error.ErrorCode;
import com.matbakhy.shared.idempotency.IdempotentCommands;
import java.nio.charset.StandardCharsets;
import java.sql.Timestamp;
import java.time.Clock;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

/**
 * Order placement (BR-022..BR-025) and the customer's order views. Placement runs in one transaction: quote
 * revalidation, stock reservation with deterministic locks, order/item/address/contact snapshots, the first event,
 * an outbox message and the cash obligation. Duplicates are prevented twice: by the idempotency record (actor +
 * command + key, 24 h) and permanently by the unique customer + clientRequestId.
 */
@Service
public class OrderService {

    private static final Logger log = LoggerFactory.getLogger(OrderService.class);

    public static final Set<String> ACTIVE = Set.of("PENDING_ACCEPTANCE", "ACCEPTED", "PREPARING", "READY", "OUT_FOR_DELIVERY");

    public record PlaceRequest(UUID quoteId, UUID clientRequestId, String termsVersion, String cancellationPolicyVersion,
                               String fulfillmentNote) {
    }

    public record Money(long amountMinor, String currency) {
    }

    public record OrderLine(UUID mealId, String title, String allergenStatement, int quantity, Money unitPrice, Money lineTotal) {
    }

    public record SlotView(UUID id, Instant startsAt, Instant endsAt, String timezone, Instant cutoffAt, int availablePortions,
                           List<String> fulfillmentModes) {
    }

    public record OrderEvent(int sequence, String fromState, String toState, Instant occurredAt, String actorType, String reasonCode) {
    }

    public record OrderView(UUID id, String publicNumber, long version, String state, String fulfillmentMode, List<OrderLine> items,
                            Money subtotal, Money deliveryFee, Money tax, Money total, SlotView slot, Instant acceptBy,
                            List<OrderEvent> events, List<String> allowedActions, String cashState, List<UUID> supportCaseIds,
                            String handoverCode, KitchenContact contact, PaymentService.PaymentView payment) {
    }

    /** Kitchen contact for the order owner after acceptance; the pickup location only for pickup orders. */
    public record KitchenContact(String kitchenName, String phone, String pickupLocation) {
    }

    /** Minimum fulfillment contact for the cook while the order is active; never the handover code. */
    public record CustomerContact(String name, String phone, Object deliveryAddress) {
    }

    public record CookOrderView(UUID id, String publicNumber, long version, String state, String fulfillmentMode, List<OrderLine> items,
                                Money subtotal, Money deliveryFee, Money tax, Money total, SlotView slot, Instant acceptBy,
                                List<OrderEvent> events, List<String> allowedActions, String cashState, String fulfillmentNote,
                                String dispatchReference, CustomerContact contact, PaymentService.PaymentView payment) {
    }

    public record CookOrderPage(List<CookOrderView> items, String nextCursor, boolean hasMore) {
    }

    public record OrderPage(List<OrderView> items, String nextCursor, boolean hasMore) {
    }

    public record OrderEventPage(List<OrderEvent> items, String nextCursor, boolean hasMore) {
    }

    private final JdbcTemplate jdbc;
    private final QuoteDirectory quotes;
    private final SlotInventory inventory;
    private final MealCatalog meals;
    private final AddressDirectory addresses;
    private final CheckoutContactPolicy contact;
    private final IdempotentCommands idempotency;
    private final JsonMapper json;
    private final KitchenDirectory kitchens;
    private final OrderCases cases;
    private final HandoverCodes codes;
    private final PaymentService payments;
    private final Clock clock;

    OrderService(JdbcTemplate jdbc, QuoteDirectory quotes, SlotInventory inventory, MealCatalog meals, AddressDirectory addresses,
                 CheckoutContactPolicy contact, IdempotentCommands idempotency, JsonMapper json, KitchenDirectory kitchens,
                 HandoverCodes codes, OrderCases cases, PaymentService payments, Clock clock) {
        this.jdbc = jdbc;
        this.quotes = quotes;
        this.inventory = inventory;
        this.meals = meals;
        this.addresses = addresses;
        this.contact = contact;
        this.idempotency = idempotency;
        this.json = json;
        this.kitchens = kitchens;
        this.codes = codes;
        this.cases = cases;
        this.payments = payments;
        this.clock = clock;
    }

    @Transactional
    public OrderView place(UUID customerId, String idempotencyKey, PlaceRequest in, boolean english) {
        UUID orderId = idempotency.execute(customerId, "order.place", idempotencyKey, in, UUID.class, () -> placeOnce(customerId, in));
        return view(customerId, orderId, english);
    }

    private UUID placeOnce(UUID customerId, PlaceRequest in) {
        // Serialize attempts carrying the same permanent request reference.
        jdbc.query("SELECT pg_advisory_xact_lock(hashtextextended(?, 0))", rs -> null, "order-request:" + customerId + ":" + in.clientRequestId());
        Map<String, Object> existing = jdbc.queryForList("SELECT id, quote_id FROM customer_order WHERE customer_id = ? AND client_request_id = ?",
                customerId, in.clientRequestId()).stream().findFirst().orElse(null);
        if (existing != null) {
            if (in.quoteId().equals(existing.get("quote_id"))) {
                return (UUID) existing.get("id");
            }
            throw new ApiException(ErrorCode.IDEMPOTENCY_CONFLICT, "clientRequestId already used for another quote",
                    List.of(new FieldError("clientRequestId", "ALREADY_USED")));
        }
        ValidQuote q = quotes.requireValid(customerId, in.quoteId());
        if (!q.termsVersion().equals(in.termsVersion()) || !q.cancellationPolicyVersion().equals(in.cancellationPolicyVersion())) {
            throw new ApiException(ErrorCode.STATE_CONFLICT, "current policies not accepted",
                    List.of(new FieldError("acceptedPolicyVersions", "POLICY_NOT_ACCEPTED")));
        }
        Boolean used = jdbc.queryForObject("SELECT EXISTS (SELECT 1 FROM customer_order WHERE quote_id = ?)", Boolean.class, in.quoteId());
        if (Boolean.TRUE.equals(used)) {
            throw new ApiException(ErrorCode.STATE_CONFLICT, "quote already used", List.of(new FieldError("quoteId", "QUOTE_ALREADY_USED")));
        }
        VerifiedContact who = contact.verifiedContact(customerId);
        Map<UUID, Integer> wanted = new LinkedHashMap<>();
        q.items().forEach(i -> wanted.put(i.mealId(), i.quantity()));
        List<Reservation> reservations = inventory.reserve(q.slotId(), wanted);

        String addressSnapshot = null;
        if (q.addressId() != null) {
            OwnedAddress a = addresses.owned(customerId, q.addressId())
                    .orElseThrow(() -> new ApiException(ErrorCode.STATE_CONFLICT, "address gone", List.of(new FieldError("quoteId", "ADDRESS_CHANGED"))));
            addressSnapshot = json.writeValueAsString(a);
        }
        Instant now = clock.instant();
        UUID orderId = UUID.randomUUID();
        Long number = jdbc.queryForObject("SELECT nextval('order_public_number_seq')", Long.class);
        long commission = Math.floorDiv(Math.addExact(Math.multiplyExact(q.subtotalMinor(), (long) q.commissionRateBps()), 5_000L), 10_000L);
        String note = in.fulfillmentNote() == null || in.fulfillmentNote().isBlank() ? null : in.fulfillmentNote().strip();
        jdbc.update("""
                INSERT INTO customer_order (id, public_number, customer_id, client_request_id, quote_id, kitchen_id, slot_id, state, fulfillment_mode,
                                            address_snapshot, contact_snapshot, fulfillment_note, subtotal_minor, delivery_fee_minor, tax_minor,
                                            total_minor, policy_version, commission_bps_snapshot, commission_minor, cancellation_policy_version,
                                            terms_version, accept_by, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, 'PENDING_ACCEPTANCE', ?, ?::jsonb, ?::jsonb, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                orderId, "MB-" + number, customerId, in.clientRequestId(), in.quoteId(), q.kitchenId(), q.slotId(), q.fulfillmentMode(),
                addressSnapshot, json.writeValueAsString(who), note, q.subtotalMinor(), q.deliveryFeeMinor(), q.taxMinor(), q.totalMinor(),
                q.policyVersion(), q.commissionRateBps(), commission, q.cancellationPolicyVersion(), q.termsVersion(), Timestamp.from(q.acceptBy()),
                Timestamp.from(now), Timestamp.from(now));
        for (QuotedItem item : q.items()) {
            String snapshot = meals.revisionSnapshot(item.mealId(), item.mealRevision())
                    .orElseThrow(() -> new IllegalStateException("missing meal revision " + item.mealId() + "/" + item.mealRevision()));
            jdbc.update("""
                    INSERT INTO order_item (id, order_id, meal_id, meal_revision, meal_snapshot, quantity, unit_price_minor, line_total_minor)
                    VALUES (?, ?, ?, ?, ?::jsonb, ?, ?, ?)""",
                    UUID.randomUUID(), orderId, item.mealId(), item.mealRevision(), snapshot, item.quantity(), item.unitPriceMinor(), item.lineTotalMinor());
        }
        for (Reservation r : reservations) {
            jdbc.update("INSERT INTO stock_allocation (id, order_id, meal_slot_id, quantity, state, created_at) VALUES (?, ?, ?, ?, 'RESERVED', ?)",
                    UUID.randomUUID(), orderId, r.mealSlotId(), r.quantity(), Timestamp.from(now));
        }
        jdbc.update("""
                INSERT INTO order_event (id, order_id, sequence, from_state, to_state, actor_type, actor_id, occurred_at)
                VALUES (?, ?, 1, NULL, 'PENDING_ACCEPTANCE', 'CUSTOMER', ?, ?)""", UUID.randomUUID(), orderId, customerId, Timestamp.from(now));
        jdbc.update("""
                INSERT INTO outbox_event (id, aggregate_type, aggregate_id, event_type, payload, available_at, created_at, request_id)
                VALUES (?, 'order', ?, 'ORDER_PLACED', ?::jsonb, ?, ?, ?)""",
                UUID.randomUUID(), orderId, json.writeValueAsString(Map.of("orderId", orderId.toString(), "kitchenId", q.kitchenId().toString())),
                Timestamp.from(now), Timestamp.from(now), org.slf4j.MDC.get(com.matbakhy.shared.web.RequestContext.REQUEST_ID_MDC_KEY));
        // MB-051: the payment terms are snapshotted with the order; cash due at hand-over is what the deposit does not cover.
        payments.createFor(orderId, customerId, q.paymentMethod(), q.totalMinor(), q.depositMinor(),
                q.recipientIdentifier() == null ? null : new PaymentService.Recipient(q.recipientMethod(), q.recipientIdentifier(), q.recipientName()),
                q.acceptBy(), now);
        jdbc.update("INSERT INTO cash_obligation (id, order_id, amount_minor, state, created_at) VALUES (?, ?, ?, 'DUE', ?)",
                UUID.randomUUID(), orderId, q.totalMinor() - q.depositMinor(), Timestamp.from(now));
        log.info("order {} recorded in its placement transaction", orderId);
        return orderId;
    }

    // ---- customer reads ----

    public OrderView get(UUID customerId, UUID orderId, boolean english) {
        return view(customerId, orderId, english);
    }

    public OrderView byRequest(UUID customerId, UUID clientRequestId, boolean english) {
        UUID id = jdbc.query("SELECT id FROM customer_order WHERE customer_id = ? AND client_request_id = ?",
                rs -> rs.next() ? rs.getObject(1, UUID.class) : null, customerId, clientRequestId);
        if (id == null) {
            throw new ApiException(ErrorCode.NOT_FOUND, "no order for this request");
        }
        return view(customerId, id, english);
    }

    public OrderPage list(UUID customerId, String stateGroup, String cursor, int limit, boolean english) {
        if (stateGroup != null && !Set.of("ACTIVE", "PAST").contains(stateGroup)) {
            throw invalid("stateGroup", "ACTIVE_OR_PAST");
        }
        if (limit < 1 || limit > 100) {
            throw invalid("limit", "RANGE_1_100");
        }
        Instant beforeTime = Instant.parse("9999-12-31T00:00:00Z");
        UUID beforeId = new UUID(-1L, -1L);
        if (cursor != null) {
            try {
                String[] parts = new String(Base64.getUrlDecoder().decode(cursor), StandardCharsets.UTF_8).split("\\|", 2);
                beforeTime = Instant.parse(parts[0]);
                beforeId = UUID.fromString(parts[1]);
            } catch (RuntimeException e) {
                throw invalid("cursor", "INVALID");
            }
        }
        String group = stateGroup == null ? "" : stateGroup.equals("ACTIVE")
                ? " AND state IN ('PENDING_ACCEPTANCE','ACCEPTED','PREPARING','READY','OUT_FOR_DELIVERY')"
                : " AND state NOT IN ('PENDING_ACCEPTANCE','ACCEPTED','PREPARING','READY','OUT_FOR_DELIVERY')";
        List<Map<String, Object>> rows = jdbc.queryForList("SELECT id, created_at FROM customer_order WHERE customer_id = ?" + group
                + " AND (created_at, id) < (?, ?) ORDER BY created_at DESC, id DESC LIMIT ?",
                customerId, Timestamp.from(beforeTime), beforeId, limit + 1);
        boolean more = rows.size() > limit;
        List<Map<String, Object>> page = more ? rows.subList(0, limit) : rows;
        String next = null;
        if (more) {
            Map<String, Object> last = page.getLast();
            next = Base64.getUrlEncoder().withoutPadding().encodeToString((((Timestamp) last.get("created_at")).toInstant() + "|" + last.get("id"))
                    .getBytes(StandardCharsets.UTF_8));
        }
        return new OrderPage(page.stream().map(r -> view(customerId, (UUID) r.get("id"), english)).toList(), next, more);
    }

    public OrderEventPage events(UUID customerId, UUID orderId, int afterSequence, int limit) {
        requireOwned(customerId, orderId);
        if (limit < 1 || limit > 100 || afterSequence < 0) {
            throw invalid("limit", "RANGE_1_100");
        }
        List<OrderEvent> events = eventsAfter(orderId, afterSequence, limit + 1);
        boolean more = events.size() > limit;
        List<OrderEvent> page = more ? events.subList(0, limit) : events;
        return new OrderEventPage(page, more ? Integer.toString(page.getLast().sequence()) : null, more);
    }

    private void requireOwned(UUID customerId, UUID orderId) {
        Boolean owned = jdbc.queryForObject("SELECT EXISTS (SELECT 1 FROM customer_order WHERE id = ? AND customer_id = ?)", Boolean.class,
                orderId, customerId);
        if (!Boolean.TRUE.equals(owned)) {
            throw new ApiException(ErrorCode.NOT_FOUND, "order not found");
        }
    }

    private List<OrderEvent> eventsAfter(UUID orderId, int afterSequence, int limit) {
        return jdbc.query("""
                SELECT sequence, from_state, to_state, occurred_at, actor_type, reason_code FROM order_event
                WHERE order_id = ? AND sequence > ? ORDER BY sequence LIMIT ?""",
                (rs, n) -> new OrderEvent(rs.getInt(1), rs.getString(2), rs.getString(3), rs.getTimestamp(4).toInstant(), rs.getString(5),
                        rs.getString(6)), orderId, afterSequence, limit);
    }

    /** Customer view; another customer's order is indistinguishable from a missing one (404). */
    private OrderView view(UUID customerId, UUID orderId, boolean english) {
        Map<String, Object> o = jdbc.queryForList("""
                SELECT o.*, s.starts_at, s.ends_at, s.cutoff_at, s.max_portions - s.reserved - s.allocated - s.consumed AS slot_available,
                       c.state AS cash_state
                FROM customer_order o JOIN cook_slot s ON s.id = o.slot_id LEFT JOIN cash_obligation c ON c.order_id = o.id
                WHERE o.id = ? AND o.customer_id = ?""", orderId, customerId).stream().findFirst()
                .orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "order not found"));
        List<OrderLine> lines = jdbc.query("""
                SELECT meal_id, meal_snapshot::text, quantity, unit_price_minor, line_total_minor FROM order_item WHERE order_id = ? ORDER BY meal_id""",
                (rs, n) -> {
                    JsonNode snap = json.readTree(rs.getString(2));
                    String title = text(snap, english ? "titleEn" : "titleAr");
                    if (title == null) {
                        title = text(snap, "titleAr");
                    }
                    return new OrderLine(rs.getObject(1, UUID.class), title == null ? "" : title, allergenStatement(snap), rs.getInt(3),
                            egp(rs.getLong(4)), egp(rs.getLong(5)));
                }, orderId);
        String state = (String) o.get("state");
        SlotView slot = new SlotView((UUID) o.get("slot_id"), ((Timestamp) o.get("starts_at")).toInstant(), ((Timestamp) o.get("ends_at")).toInstant(),
                "Africa/Cairo", ((Timestamp) o.get("cutoff_at")).toInstant(), Math.max(0, ((Number) o.get("slot_available")).intValue()),
                List.of((String) o.get("fulfillment_mode")));
        // After acceptance the customer can only ask (a support case); staff decide (BR-028).
        List<String> actions = "PENDING_ACCEPTANCE".equals(state) ? List.of("CANCEL")
                : CONTACT_STATES.contains(state) ? List.of("REQUEST_CANCELLATION") : List.of();
        String mode = (String) o.get("fulfillment_mode");
        KitchenContact kitchenContact = null;
        if (CONTACT_STATES.contains(state)) {
            FulfillmentContact k = kitchens.fulfillmentContact((UUID) o.get("kitchen_id")).orElse(null);
            if (k != null) {
                kitchenContact = new KitchenContact(k.displayName(), k.contactPhone(), "PICKUP".equals(mode) ? k.pickupLocation() : null);
            }
        }
        return new OrderView(orderId, (String) o.get("public_number"), (Long) o.get("version"), state, mode, lines,
                egp((Long) o.get("subtotal_minor")), egp((Long) o.get("delivery_fee_minor")), egp((Long) o.get("tax_minor")),
                egp((Long) o.get("total_minor")), slot, ((Timestamp) o.get("accept_by")).toInstant(), eventsAfter(orderId, 0, 1000), actions,
                o.get("cash_state") == null ? "NOT_DUE" : (String) o.get("cash_state"), cases.caseIds(orderId), handoverCode(orderId, state), kitchenContact,
                payments.view(orderId).orElse(null));
    }

    static final Set<String> CONTACT_STATES = Set.of("ACCEPTED", "PREPARING", "READY", "OUT_FOR_DELIVERY");

    /** Only for the order owner, while READY or out for delivery and the challenge is usable. */
    private String handoverCode(UUID orderId, String state) {
        if (!"READY".equals(state) && !"OUT_FOR_DELIVERY".equals(state)) {
            return null;
        }
        return jdbc.query("SELECT ciphertext, nonce FROM handover_challenge "
                + "WHERE order_id = ? AND consumed_at IS NULL AND locked_at IS NULL AND expires_at > ?",
                rs -> rs.next() ? codes.reveal(orderId, rs.getBytes(1), rs.getBytes(2)) : null, orderId, Timestamp.from(clock.instant()));
    }

    /** Staff view after an ops command: never the customer's handover code or contact details. */
    public OrderView staffView(UUID orderId) {
        UUID customer = jdbc.query("SELECT customer_id FROM customer_order WHERE id = ?", rs -> rs.next() ? rs.getObject(1, UUID.class) : null, orderId);
        if (customer == null) {
            throw new ApiException(ErrorCode.NOT_FOUND, "order not found");
        }
        OrderView v = view(customer, orderId, false);
        return new OrderView(v.id(), v.publicNumber(), v.version(), v.state(), v.fulfillmentMode(), v.items(), v.subtotal(), v.deliveryFee(), v.tax(),
                v.total(), v.slot(), v.acceptBy(), v.events(), List.of(), v.cashState(), v.supportCaseIds(), null, null, v.payment());
    }

    // ---- cook reads ----

    private UUID cookKitchen(UUID cookId) {
        return kitchens.ownedBy(cookId).map(KitchenDirectory.KitchenStatus::kitchenId)
                .orElseThrow(() -> new ApiException(ErrorCode.FORBIDDEN, "not a cook"));
    }

    public CookOrderPage cookOrders(UUID cookId, String state, String cursor, int limit, boolean english) {
        UUID kitchen = cookKitchen(cookId);
        if (state != null && !OrderLifecycleService.TERMINAL.contains(state) && !ACTIVE.contains(state)) {
            throw invalid("state", "UNKNOWN_STATE");
        }
        if (limit < 1 || limit > 100) {
            throw invalid("limit", "RANGE_1_100");
        }
        Instant afterTime = Instant.EPOCH;
        UUID afterId = new UUID(0, 0);
        if (cursor != null) {
            try {
                String[] parts = new String(Base64.getUrlDecoder().decode(cursor), StandardCharsets.UTF_8).split("\\|", 2);
                afterTime = Instant.parse(parts[0]);
                afterId = UUID.fromString(parts[1]);
            } catch (RuntimeException e) {
                throw invalid("cursor", "INVALID");
            }
        }
        List<Map<String, Object>> rows = jdbc.queryForList("SELECT id, created_at FROM customer_order WHERE kitchen_id = ? "
                + "AND (?::text IS NULL OR state = ?) AND (created_at, id) > (?, ?) ORDER BY created_at, id LIMIT ?",
                kitchen, state, state, Timestamp.from(afterTime), afterId, limit + 1);
        boolean more = rows.size() > limit;
        List<Map<String, Object>> page = more ? rows.subList(0, limit) : rows;
        String next = null;
        if (more) {
            Map<String, Object> last = page.getLast();
            next = Base64.getUrlEncoder().withoutPadding().encodeToString((((Timestamp) last.get("created_at")).toInstant() + "|" + last.get("id"))
                    .getBytes(StandardCharsets.UTF_8));
        }
        return new CookOrderPage(page.stream().map(r -> cookView(kitchen, (UUID) r.get("id"), english)).toList(), next, more);
    }

    public CookOrderView cookOrder(UUID cookId, UUID orderId, boolean english) {
        return cookView(cookKitchen(cookId), orderId, english);
    }

    /** Cook view scoped to the kitchen (another kitchen's order is 404); contact only while the order is active. */
    private CookOrderView cookView(UUID kitchenId, UUID orderId, boolean english) {
        UUID customer = jdbc.query("SELECT customer_id FROM customer_order WHERE id = ? AND kitchen_id = ?",
                rs -> rs.next() ? rs.getObject(1, UUID.class) : null, orderId, kitchenId);
        if (customer == null) {
            throw new ApiException(ErrorCode.NOT_FOUND, "order not found");
        }
        OrderView v = view(customer, orderId, english);
        Map<String, Object> o = jdbc.queryForMap("SELECT contact_snapshot::text AS contact, address_snapshot::text AS address, "
                + "fulfillment_note, dispatch_reference FROM customer_order WHERE id = ?", orderId);
        CustomerContact contact = null;
        if (CONTACT_STATES.contains(v.state())) {
            JsonNode c = json.readTree((String) o.get("contact"));
            Object address = o.get("address") == null ? null : json.readTree((String) o.get("address"));
            contact = new CustomerContact(text(c, "displayName"), text(c, "phoneE164"), address);
        }
        boolean showNote = CONTACT_STATES.contains(v.state()) || "PENDING_ACCEPTANCE".equals(v.state());
        return new CookOrderView(v.id(), v.publicNumber(), v.version(), v.state(), v.fulfillmentMode(), v.items(), v.subtotal(), v.deliveryFee(),
                v.tax(), v.total(), v.slot(), v.acceptBy(), v.events(), cookActions(v.state(), v.fulfillmentMode()), v.cashState(),
                showNote ? (String) o.get("fulfillment_note") : null, (String) o.get("dispatch_reference"), contact, v.payment());
    }

    private static List<String> cookActions(String state, String mode) {
        return switch (state) {
            case "PENDING_ACCEPTANCE" -> List.of("ACCEPT", "REJECT");
            case "ACCEPTED" -> List.of("PREPARE", "CANCEL");
            case "PREPARING" -> List.of("READY");
            case "READY" -> "PICKUP".equals(mode) ? List.of("HANDOVER") : List.of("DISPATCH");
            case "OUT_FOR_DELIVERY" -> List.of("HANDOVER", "DELIVERY_FAILURE");
            default -> List.of();
        };
    }

    private static String text(JsonNode node, String field) {
        JsonNode v = node.get(field);
        return v == null || v.isNull() ? null : v.asString();
    }

    /** Snapshot of the declaration at order time: codes for CONTAINS, otherwise NONE_DECLARED or UNKNOWN, plus the cook's note. */
    private static String allergenStatement(JsonNode snap) {
        String declaration = text(snap, "allergenDeclaration");
        List<String> codes = new ArrayList<>();
        JsonNode list = snap.get("allergenCodes");
        if (list != null) {
            list.forEach(c -> codes.add(c.asString()));
        }
        String base = "CONTAINS".equals(declaration) ? String.join(", ", codes) : declaration == null ? "UNKNOWN" : declaration;
        String note = text(snap, "allergenNote");
        return note == null ? base : base + " — " + note;
    }

    private static Money egp(long minor) {
        return new Money(minor, "EGP");
    }

    private static ApiException invalid(String field, String code) {
        return new ApiException(ErrorCode.VALIDATION_FAILED, "invalid " + field, List.of(new FieldError(field, code)));
    }
}
package com.matbakhy.orders.internal;

import com.matbakhy.cooks.api.KitchenDirectory;
import com.matbakhy.operations.api.AuditLog;
import com.matbakhy.orders.api.OrderCases;
import com.matbakhy.shared.error.ApiException;
import com.matbakhy.shared.error.ApiException.FieldError;
import com.matbakhy.shared.error.ErrorCode;
import java.sql.Timestamp;
import java.time.Clock;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * MB-051 (owner decision D16): eligible cash on delivery and manual deposits paid by the customer directly to the
 * kitchen's approved recipient. Matbakhy never holds the money. The payment state is kept apart from the order and its
 * fulfilment. A customer's transfer report is not payment. The kitchen's acknowledgement, given after it checks its
 * own account, is recorded as reported by the kitchen and never as bank verification. Preparation of a deposit order
 * waits for that report. Closing an order after a reported transfer leads to reconciliation, never to a silent close.
 */
@Service
public class PaymentService {

    public enum Method { COD, DEPOSIT }

    public record Money(long amountMinor, String currency) {
    }

    public record Recipient(String method, String identifier, String name) {
    }

    /** Payment terms in a quote. */
    public record Terms(String method, int depositBps, Money deposit, Money remainder, Recipient recipient) {
    }

    public record PaymentView(String method, String state, Money deposit, Money remainder, Recipient recipient, Instant depositExpiresAt,
                              long version) {
    }

    record Profile(int depositBps, Long codMaxTotalMinor, Recipient recipient) {
    }

    /** The kitchen's own view of its payment terms; the recipient is offered to customers only once APPROVED. */
    public record ProfileView(int depositBps, Long codMaxTotalMinor, Recipient recipient, String recipientStatus, long version) {
    }

    public enum Problem { NOT_RECEIVED, AMOUNT_MISMATCH }

    /** Staff outcomes on an ended order. Deliberately no outcome that marks money as received. */
    public enum Decision { REFUND_OWED, CLOSED_NO_FUNDS }

    public record QueueItem(UUID orderId, String publicNumber, UUID kitchenId, String orderState, String state, Money deposit,
                            String lastReason, Instant updatedAt, long version) {
    }

    private static final Set<String> AFTER_TRANSFER = Set.of("CUSTOMER_TRANSFER_REPORTED", "KITCHEN_RECEIPT_REPORTED", "DISPUTED");

    private final JdbcTemplate jdbc;
    private final KitchenDirectory kitchens;
    private final AuditLog audit;
    private final Clock clock;
    private final OrderCases cases;

    PaymentService(JdbcTemplate jdbc, KitchenDirectory kitchens, AuditLog audit, Clock clock, OrderCases cases) {
        this.jdbc = jdbc;
        this.kitchens = kitchens;
        this.audit = audit;
        this.clock = clock;
        this.cases = cases;
    }

    private static final Set<String> ENDED = Set.of("COMPLETED", "REJECTED", "EXPIRED", "CANCELLED", "DELIVERY_FAILED");

    private UUID ownKitchen(UUID cookId) {
        return kitchens.ownedBy(cookId).map(KitchenDirectory.KitchenStatus::kitchenId)
                .orElseThrow(() -> new ApiException(ErrorCode.FORBIDDEN, "not a cook"));
    }

    // ---- MB-052: the kitchen's payment profile and its approval ----

    public ProfileView profileOf(UUID cookId) {
        return profileView(ownKitchen(cookId));
    }

    private ProfileView profileView(UUID kitchenId) {
        return jdbc.query("""
                SELECT deposit_bps, cod_max_total_minor, recipient_method, recipient_identifier, recipient_name, recipient_status, version
                FROM kitchen_payment_profile WHERE kitchen_id = ?""", rs -> rs.next()
                ? new ProfileView(rs.getInt(1), (Long) rs.getObject(2),
                        rs.getString(4) == null ? null : new Recipient(rs.getString(3), rs.getString(4), rs.getString(5)), rs.getString(6), rs.getLong(7))
                : new ProfileView(0, null, null, "NONE", 0), kitchenId);
    }

    /**
     * The kitchen sets its deposit share, its COD cap and the account customers pay. A new or changed recipient is not
     * offered to customers until staff approve it again.
     */
    @Transactional
    public ProfileView updateProfile(UUID cookId, long expectedVersion, int depositBps, Long codMaxTotalMinor, Recipient r) {
        UUID kitchen = ownKitchen(cookId);
        if (depositBps < 0 || depositBps > 10_000) {
            throw invalid("depositBps", "RANGE_0_10000");
        }
        if (codMaxTotalMinor != null && codMaxTotalMinor < 0) {
            throw invalid("codMaxTotalMinor", "NOT_NEGATIVE");
        }
        if (depositBps > 0 && r == null) {
            throw invalid("recipient", "REQUIRED_FOR_DEPOSIT");
        }
        if (r != null && (r.method() == null || !Set.of("INSTAPAY", "MOBILE_WALLET", "BANK_TRANSFER").contains(r.method())
                || r.identifier() == null || r.identifier().strip().length() < 3 || r.identifier().strip().length() > 64
                || r.name() == null || r.name().strip().length() < 2 || r.name().strip().length() > 80)) {
            throw invalid("recipient", "INVALID_RECIPIENT");
        }
        ProfileView current = profileView(kitchen);
        if (current.version() != expectedVersion) {
            throw new ApiException(ErrorCode.VERSION_CONFLICT, "payment profile changed");
        }
        Recipient next = r == null ? null : new Recipient(r.method(), r.identifier().strip(), r.name().strip());
        boolean sameRecipient = java.util.Objects.equals(next, current.recipient());
        String status = sameRecipient && next != null ? current.recipientStatus() : "NONE";
        int n = jdbc.update("""
                INSERT INTO kitchen_payment_profile (kitchen_id, deposit_bps, cod_max_total_minor, recipient_method, recipient_identifier, recipient_name,
                                                     recipient_status, version)
                VALUES (?, ?, ?, ?, ?, ?, 'NONE', 1)
                ON CONFLICT (kitchen_id) DO UPDATE SET deposit_bps = EXCLUDED.deposit_bps, cod_max_total_minor = EXCLUDED.cod_max_total_minor,
                    recipient_method = EXCLUDED.recipient_method, recipient_identifier = EXCLUDED.recipient_identifier,
                    recipient_name = EXCLUDED.recipient_name, recipient_status = ?,
                    approved_by = CASE WHEN ? = 'APPROVED' THEN kitchen_payment_profile.approved_by END,
                    approved_at = CASE WHEN ? = 'APPROVED' THEN kitchen_payment_profile.approved_at END,
                    version = kitchen_payment_profile.version + 1
                WHERE kitchen_payment_profile.version = ?""",
                kitchen, depositBps, codMaxTotalMinor, next == null ? null : next.method(), next == null ? null : next.identifier(),
                next == null ? null : next.name(), status, status, status, expectedVersion);
        if (n != 1) {
            throw new ApiException(ErrorCode.VERSION_CONFLICT, "payment profile changed");
        }
        audit.record(new AuditLog.Entry(cookId, "payment.profile_update", null, "kitchen", kitchen.toString(), AuditLog.Outcome.ALLOWED, null,
                requestId(), Map.of("depositBps", depositBps, "recipientChanged", !sameRecipient)));
        return profileView(kitchen);
    }

    public record PendingRecipient(UUID kitchenId, String kitchenName, Recipient recipient, long version) {
    }

    /** Kitchens whose recipient waits for approval (finance.verify), oldest first. */
    public List<PendingRecipient> pendingRecipients() {
        return jdbc.query("""
                SELECT kitchen_id, recipient_method, recipient_identifier, recipient_name, version FROM kitchen_payment_profile
                WHERE recipient_status = 'NONE' AND recipient_identifier IS NOT NULL ORDER BY kitchen_id LIMIT 100""",
                (rs, n) -> {
                    UUID k = rs.getObject(1, UUID.class);
                    String name = kitchens.fulfillmentContact(k).map(KitchenDirectory.FulfillmentContact::displayName).orElse("");
                    return new PendingRecipient(k, name, new Recipient(rs.getString(2), rs.getString(3), rs.getString(4)), rs.getLong(5));
                });
    }

    /** Staff (finance.verify, recent MFA) approve the recipient after checking it against the approved cook. Audited. */
    @Transactional
    public ProfileView approveRecipient(UUID staffId, UUID kitchenId, long expectedVersion, String reason) {
        if (reason == null || reason.strip().length() < 10 || reason.strip().length() > 500) {
            throw invalid("reason", "LENGTH_10_500");
        }
        if (kitchens.ownedBy(staffId).map(KitchenDirectory.KitchenStatus::kitchenId).filter(kitchenId::equals).isPresent()) {
            throw new ApiException(ErrorCode.FORBIDDEN, "cannot approve your own kitchen's recipient");
        }
        ProfileView current = profileView(kitchenId);
        if (current.recipient() == null || current.version() == 0) {
            throw new ApiException(ErrorCode.STATE_CONFLICT, "no recipient to approve", List.of(new FieldError("recipient", "MISSING")));
        }
        int n = jdbc.update("""
                UPDATE kitchen_payment_profile SET recipient_status = 'APPROVED', approved_by = ?, approved_at = ?, version = version + 1
                WHERE kitchen_id = ? AND version = ?""", staffId, Timestamp.from(clock.instant()), kitchenId, expectedVersion);
        if (n != 1) {
            throw new ApiException(ErrorCode.VERSION_CONFLICT, "payment profile changed");
        }
        audit.record(new AuditLog.Entry(staffId, "payment.recipient_approve", "finance.verify", "kitchen", kitchenId.toString(),
                AuditLog.Outcome.ALLOWED, reason.strip(), requestId(), Map.of("method", current.recipient().method())));
        return profileView(kitchenId);
    }


    /** The kitchen's current terms; {@code lock} takes a share lock so a change serializes with a placement (as in D13). */
    Profile profile(UUID kitchenId, boolean lock) {
        return jdbc.query("""
                SELECT deposit_bps, cod_max_total_minor, recipient_method, recipient_identifier, recipient_name, recipient_status
                FROM kitchen_payment_profile WHERE kitchen_id = ?""" + (lock ? " FOR SHARE" : ""), rs -> {
            if (!rs.next()) {
                return new Profile(0, null, null);
            }
            Recipient r = "APPROVED".equals(rs.getString(6))
                    ? new Recipient(rs.getString(3), rs.getString(4), rs.getString(5)) : null;
            return new Profile(rs.getInt(1), (Long) rs.getObject(2), r);
        }, kitchenId);
    }

    /** Server-derived terms for a quote: integer EGP, deposit rounded half up, the rest due at hand-over. */
    Terms terms(Profile p, Method method, long totalMinor) {
        if (method == Method.COD) {
            if (p.codMaxTotalMinor() != null && totalMinor > p.codMaxTotalMinor()) {
                throw invalid("paymentMethod", "COD_NOT_ELIGIBLE");
            }
            return new Terms("COD", 0, egp(0), egp(totalMinor), null);
        }
        if (p.depositBps() == 0 || p.recipient() == null) {
            throw invalid("paymentMethod", "DEPOSIT_NOT_OFFERED");
        }
        long deposit = Math.max(1, Math.floorDiv(Math.addExact(Math.multiplyExact(totalMinor, (long) p.depositBps()), 5_000L), 10_000L));
        return new Terms("DEPOSIT", p.depositBps(), egp(deposit), egp(totalMinor - deposit), p.recipient());
    }

    /** Writes the immutable payment record of a new order; the deposit is due by the acceptance deadline. */
    void createFor(UUID orderId, UUID customerId, String method, long totalMinor, long depositMinor, Recipient r, Instant acceptBy, Instant now) {
        boolean deposit = "DEPOSIT".equals(method);
        String state = deposit ? "WAITING_FOR_DEPOSIT" : "NOT_REQUIRED";
        jdbc.update("""
                INSERT INTO order_payment (order_id, method, total_minor, deposit_minor, remainder_minor, recipient_method, recipient_identifier,
                                           recipient_name, deposit_expires_at, state, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                orderId, method, totalMinor, depositMinor, totalMinor - depositMinor, deposit ? r.method() : null, deposit ? r.identifier() : null,
                deposit ? r.name() : null, deposit ? Timestamp.from(acceptBy) : null, state, Timestamp.from(now));
        if (deposit) {
            event(orderId, null, state, "CUSTOMER", customerId, depositMinor, null, null, now);
        }
    }

    public Optional<PaymentView> view(UUID orderId) {
        return jdbc.query("""
                SELECT method, state, deposit_minor, remainder_minor, recipient_method, recipient_identifier, recipient_name, deposit_expires_at, version
                FROM order_payment WHERE order_id = ?""", (rs, n) -> new PaymentView(rs.getString(1), rs.getString(2), egp(rs.getLong(3)),
                egp(rs.getLong(4)), rs.getString(6) == null ? null : new Recipient(rs.getString(5), rs.getString(6), rs.getString(7)),
                rs.getTimestamp(8) == null ? null : rs.getTimestamp(8).toInstant(), rs.getLong(9)), orderId).stream().findFirst();
    }

    /**
     * The customer says the deposit was sent. Idempotent: a repeated or concurrent report changes nothing more. The
     * report is information for the kitchen, not payment.
     */
    @Transactional
    public PaymentView reportTransfer(UUID customerId, UUID orderId, String reference) {
        Map<String, Object> p = lockForCustomer(customerId, orderId);
        String state = (String) p.get("state");
        if ("CUSTOMER_TRANSFER_REPORTED".equals(state) || "KITCHEN_RECEIPT_REPORTED".equals(state)) {
            return view(orderId).orElseThrow();
        }
        if (!"WAITING_FOR_DEPOSIT".equals(state)) {
            throw new ApiException(ErrorCode.STATE_CONFLICT, "no deposit is waiting", List.of(new FieldError("payment", "NO_DEPOSIT_WAITING")));
        }
        move(orderId, state, "CUSTOMER_TRANSFER_REPORTED", (Long) p.get("version"), "CUSTOMER", customerId, null, reference, null);
        return view(orderId).orElseThrow();
    }

    /**
     * The kitchen reports that the deposit arrived in its own account. Recorded as the kitchen's statement, not as a
     * bank confirmation. The amount must equal the deposit; a different amount or "not received" is MB-052.
     */
    @Transactional
    public PaymentView kitchenReceipt(UUID cookId, UUID orderId, long expectedVersion, long amountMinor, String reference) {
        UUID kitchen = ownKitchen(cookId);
        Map<String, Object> p = jdbc.queryForList("""
                SELECT p.state, p.version, p.deposit_minor, o.state AS order_state FROM order_payment p JOIN customer_order o ON o.id = p.order_id
                WHERE p.order_id = ? AND o.kitchen_id = ? FOR UPDATE OF p""", orderId, kitchen).stream().findFirst()
                .orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "order not found"));
        String state = (String) p.get("state");
        if (ENDED.contains((String) p.get("order_state"))) {
            throw new ApiException(ErrorCode.STATE_CONFLICT, "order ended; report a refund instead", List.of(new FieldError("payment", "ORDER_ENDED")));
        }
        if (!Set.of("WAITING_FOR_DEPOSIT", "CUSTOMER_TRANSFER_REPORTED", "DISPUTED").contains(state)) {
            throw new ApiException(ErrorCode.STATE_CONFLICT, "no deposit is waiting", List.of(new FieldError("payment", "NO_DEPOSIT_WAITING")));
        }
        if ((Long) p.get("version") != expectedVersion) {
            throw new ApiException(ErrorCode.VERSION_CONFLICT, "payment changed");
        }
        if (amountMinor != (Long) p.get("deposit_minor")) {
            throw invalid("amountMinor", "DOES_NOT_MATCH_DEPOSIT");
        }
        move(orderId, state, "KITCHEN_RECEIPT_REPORTED", expectedVersion, "COOK", cookId, amountMinor, reference, null);
        return view(orderId).orElseThrow();
    }

    /** The kitchen reports that nothing arrived, or a different amount (TC-161). Processing pauses; ops see it in their queue. */
    @Transactional
    public PaymentView reportProblem(UUID cookId, UUID orderId, long expectedVersion, Problem kind, Long amountSeen, String reference) {
        if (kind == Problem.AMOUNT_MISMATCH && (amountSeen == null || amountSeen < 0)) {
            throw invalid("amountMinor", "REQUIRED_FOR_MISMATCH");
        }
        Map<String, Object> p = lockForKitchen(cookId, orderId);
        String state = (String) p.get("state");
        if (!Set.of("WAITING_FOR_DEPOSIT", "CUSTOMER_TRANSFER_REPORTED", "RECONCILE_PENDING").contains(state)) {
            throw new ApiException(ErrorCode.STATE_CONFLICT, "nothing to dispute", List.of(new FieldError("payment", "NOTHING_TO_DISPUTE")));
        }
        checkVersion(p, expectedVersion);
        move(orderId, state, "DISPUTED", expectedVersion, "COOK", cookId, kind == Problem.AMOUNT_MISMATCH ? amountSeen : null, reference, kind.name());
        return view(orderId).orElseThrow();
    }

    /** Payments that need ops attention, newest first (finance.verify). */
    public List<QueueItem> queue(String state) {
        if (!Set.of("DISPUTED", "RECONCILE_PENDING", "REFUND_OWED").contains(state)) {
            throw invalid("state", "ALLOWED_DISPUTED|RECONCILE_PENDING|REFUND_OWED");
        }
        return jdbc.query("""
                SELECT p.order_id, o.public_number, o.kitchen_id, o.state, p.state, p.deposit_minor, p.updated_at, p.version,
                       (SELECT e.reason_code FROM payment_event e WHERE e.order_id = p.order_id AND e.reason_code IS NOT NULL
                        ORDER BY e.occurred_at DESC LIMIT 1)
                FROM order_payment p JOIN customer_order o ON o.id = p.order_id WHERE p.state = ? ORDER BY p.updated_at DESC LIMIT 100""",
                (rs, n) -> new QueueItem(rs.getObject(1, UUID.class), rs.getString(2), rs.getObject(3, UUID.class), rs.getString(4), rs.getString(5),
                        egp(rs.getLong(6)), rs.getString(9), rs.getTimestamp(7).toInstant(), rs.getLong(8)), state);
    }

    /**
     * Staff decide on an ended order's open payment, with a reason (audited): the kitchen owes a refund, or the matter
     * is closed without funds. There is no decision that marks money as received.
     */
    @Transactional
    public PaymentView decide(UUID staffId, UUID orderId, long expectedVersion, Decision outcome, String reason) {
        if (reason == null || reason.strip().length() < 10 || reason.strip().length() > 500) {
            throw invalid("reason", "LENGTH_10_500");
        }
        Map<String, Object> p = jdbc.queryForList("""
                SELECT p.state, p.version, o.state AS order_state FROM order_payment p JOIN customer_order o ON o.id = p.order_id
                WHERE p.order_id = ? FOR UPDATE OF p""", orderId).stream().findFirst()
                .orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "order not found"));
        if (!ENDED.contains((String) p.get("order_state"))) {
            throw new ApiException(ErrorCode.STATE_CONFLICT, "decide once the order has ended", List.of(new FieldError("orderId", "ORDER_ACTIVE")));
        }
        String state = (String) p.get("state");
        if (!Set.of("DISPUTED", "RECONCILE_PENDING").contains(state)) {
            throw new ApiException(ErrorCode.STATE_CONFLICT, "nothing to decide", List.of(new FieldError("payment", "NOTHING_TO_DECIDE")));
        }
        checkVersion(p, expectedVersion);
        move(orderId, state, outcome.name(), expectedVersion, "STAFF", staffId, null, null, outcome.name());
        audit.record(new AuditLog.Entry(staffId, "payment.decision", "finance.verify", "order", orderId.toString(), AuditLog.Outcome.ALLOWED,
                reason.strip(), requestId(), Map.of("outcome", outcome.name(), "from", state)));
        return view(orderId).orElseThrow();
    }

    /** The kitchen reports the refund it sent, with the transfer reference (its statement, not a bank confirmation). */
    @Transactional
    public PaymentView reportRefund(UUID cookId, UUID orderId, long expectedVersion, String reference) {
        if (reference == null || reference.isBlank() || reference.strip().length() > 64) {
            throw invalid("reference", "REQUIRED");
        }
        Map<String, Object> p = lockForKitchen(cookId, orderId);
        String state = (String) p.get("state");
        if (!Set.of("REFUND_OWED", "RECONCILE_PENDING").contains(state)) {
            throw new ApiException(ErrorCode.STATE_CONFLICT, "no refund due", List.of(new FieldError("payment", "NO_REFUND_DUE")));
        }
        checkVersion(p, expectedVersion);
        move(orderId, state, "REFUNDED", expectedVersion, "COOK", cookId, (Long) p.get("deposit_minor"), reference, null);
        return view(orderId).orElseThrow();
    }

    private Map<String, Object> lockForKitchen(UUID cookId, UUID orderId) {
        UUID kitchen = ownKitchen(cookId);
        return jdbc.queryForList("""
                SELECT p.state, p.version, p.deposit_minor FROM order_payment p JOIN customer_order o ON o.id = p.order_id
                WHERE p.order_id = ? AND o.kitchen_id = ? FOR UPDATE OF p""", orderId, kitchen).stream().findFirst()
                .orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "order not found"));
    }

    private static void checkVersion(Map<String, Object> p, long expected) {
        if ((Long) p.get("version") != expected) {
            throw new ApiException(ErrorCode.VERSION_CONFLICT, "payment changed");
        }
    }

    private static String requestId() {
        return org.slf4j.MDC.get(com.matbakhy.shared.web.RequestContext.REQUEST_ID_MDC_KEY);
    }

    /** No preparation of a deposit order before the kitchen has reported receipt (TC-159). */
    void requireReadyForPreparation(UUID orderId) {
        String state = jdbc.query("SELECT state FROM order_payment WHERE order_id = ?", rs -> rs.next() ? rs.getString(1) : null, orderId);
        if (state != null && !"NOT_REQUIRED".equals(state) && !"KITCHEN_RECEIPT_REPORTED".equals(state)) {
            throw new ApiException(ErrorCode.STATE_CONFLICT, "deposit not reported received by the kitchen",
                    List.of(new FieldError("payment", "DEPOSIT_NOT_RECEIVED")));
        }
    }

    /**
     * The order ended without fulfilment (expired, rejected or cancelled). A deposit nobody reported expires; once a
     * transfer was reported by either side, the payment needs reconciliation (refund or confirmation that nothing
     * arrived), never a silent close (TC-160).
     */
    void orderClosed(UUID orderId, String actorType, UUID actorId, String reasonCode) {
        Map<String, Object> p = jdbc.queryForList("SELECT state, version FROM order_payment WHERE order_id = ? FOR UPDATE", orderId).stream()
                .findFirst().orElse(null);
        if (p == null) {
            return;
        }
        String state = (String) p.get("state");
        String to = "WAITING_FOR_DEPOSIT".equals(state) ? "EXPIRED" : AFTER_TRANSFER.contains(state) ? "RECONCILE_PENDING" : null;
        if (to != null) {
            move(orderId, state, to, (Long) p.get("version"), actorType, actorId, null, null, reasonCode);
        }
    }

    private Map<String, Object> lockForCustomer(UUID customerId, UUID orderId) {
        return jdbc.queryForList("""
                SELECT p.state, p.version FROM order_payment p JOIN customer_order o ON o.id = p.order_id
                WHERE p.order_id = ? AND o.customer_id = ? FOR UPDATE OF p""", orderId, customerId).stream().findFirst()
                .orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "order not found"));
    }

    private void move(UUID orderId, String from, String to, long version, String actorType, UUID actorId, Long amount, String reference,
                      String reasonCode) {
        Instant now = clock.instant();
        int updated = jdbc.update("UPDATE order_payment SET state = ?, version = version + 1, updated_at = ? WHERE order_id = ? AND version = ? AND state = ?",
                to, Timestamp.from(now), orderId, version, from);
        if (updated != 1) {
            throw new ApiException(ErrorCode.VERSION_CONFLICT, "payment changed concurrently");
        }
        event(orderId, from, to, actorType, actorId, amount, reference, reasonCode, now);
        if (NEEDS_CASE.contains(to)) {
            cases.openPaymentCase(orderId, to);
        }
    }

    /** Payment states that need a human: staff own them through one open PAYMENT support case per order (MB-052). */
    static final Set<String> NEEDS_CASE = Set.of("DISPUTED", "RECONCILE_PENDING", "REFUND_OWED");

    private void event(UUID orderId, String from, String to, String actorType, UUID actorId, Long amount, String reference, String reasonCode,
                       Instant at) {
        jdbc.update("""
                INSERT INTO payment_event (id, order_id, from_state, to_state, actor_type, actor_id, amount_minor, reference, reason_code, request_id,
                                           occurred_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                UUID.randomUUID(), orderId, from, to, actorType, actorId, amount, reference == null || reference.isBlank() ? null : reference.strip(),
                reasonCode, org.slf4j.MDC.get(com.matbakhy.shared.web.RequestContext.REQUEST_ID_MDC_KEY), Timestamp.from(at));
        if (NOTIFIED.contains(to)) {
            // MB-052 follow-up: the other party hears about it (in-app; channels per O07), in the same transaction.
            jdbc.update("""
                    INSERT INTO outbox_event (id, aggregate_type, aggregate_id, event_type, payload, available_at, created_at, request_id)
                    VALUES (?, 'order', ?, ?, ?::jsonb, ?, ?, ?)""",
                    UUID.randomUUID(), orderId, "PAYMENT_" + to, "{\"orderId\":\"" + orderId + "\",\"state\":\"PAYMENT_" + to + "\"}",
                    Timestamp.from(at), Timestamp.from(at), org.slf4j.MDC.get(com.matbakhy.shared.web.RequestContext.REQUEST_ID_MDC_KEY));
        }
    }

    /** Payment states the other party is told about: the customer's report goes to the kitchen, the rest to the customer. */
    static final java.util.Set<String> NOTIFIED = java.util.Set.of("CUSTOMER_TRANSFER_REPORTED", "KITCHEN_RECEIPT_REPORTED", "DISPUTED",
            "REFUND_OWED", "REFUNDED");

    private static Money egp(long minor) {
        return new Money(minor, "EGP");
    }

    private static ApiException invalid(String field, String code) {
        return new ApiException(ErrorCode.VALIDATION_FAILED, "invalid " + field, List.of(new FieldError(field, code)));
    }
}

package com.matbakhy.app.security;

import com.matbakhy.app.config.MatbakhyProperties;
import com.matbakhy.app.config.MatbakhyProperties.DeploymentEnvironment;
import java.nio.charset.StandardCharsets;
import java.time.Clock;
import java.util.List;
import java.util.Map;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.annotation.Order;
import org.springframework.http.HttpMethod;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.oauth2.client.oidc.authentication.OidcIdTokenDecoderFactory;
import org.springframework.security.oauth2.client.registration.ClientRegistration;
import org.springframework.security.oauth2.client.registration.ClientRegistrationRepository;
import org.springframework.security.oauth2.client.registration.InMemoryClientRegistrationRepository;
import org.springframework.security.oauth2.core.AuthorizationGrantType;
import org.springframework.security.oauth2.core.ClientAuthenticationMethod;
import org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;
import org.springframework.security.oauth2.core.OAuth2Error;
import org.springframework.security.oauth2.core.OAuth2TokenValidatorResult;
import org.springframework.security.oauth2.core.oidc.user.OidcUser;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.security.oauth2.jwt.JwtDecoder;
import org.springframework.security.oauth2.jwt.JwtIssuerValidator;
import org.springframework.security.oauth2.jwt.JwtTimestampValidator;
import org.springframework.security.oauth2.jwt.NimbusJwtDecoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.access.intercept.AuthorizationFilter;
import org.springframework.security.web.authentication.logout.LogoutSuccessHandler;
import org.springframework.security.oauth2.client.authentication.OAuth2AuthenticationToken;
import org.springframework.session.web.http.CookieSerializer;
import org.springframework.session.web.http.DefaultCookieSerializer;
import org.springframework.web.cors.CorsConfiguration;
import org.springframework.web.cors.CorsConfigurationSource;
import org.springframework.web.cors.UrlBasedCorsConfigurationSource;
import org.springframework.web.util.UriComponentsBuilder;

/**
 * Two chains (ADR-003):
 * <ol>
 *   <li>Native/API clients with {@code Authorization: Bearer}: stateless JWT validation (issuer, audience,
 *       signature, expiry). No cookies are read, so no CSRF token is needed.</li>
 *   <li>Web: OIDC authorization-code login with a server-side session (PostgreSQL), HttpOnly cookie,
 *       CSRF token on every mutation and a strict CORS allowlist.</li>
 * </ol>
 * Authorities come only from server-side state; token role claims are ignored.
 */
@Configuration(proxyBeanMethods = false)
@EnableMethodSecurity
@EnableConfigurationProperties(IdentityProperties.class)
class SecurityConfiguration {

    static final String REGISTRATION_ID = "keycloak";
    static final String DELETION_REQUEST = "/api/v1/me/deletion-requests";
    /** MB-054: anonymous browsing activity (no data returned; deduplicated, capped and stored without identity). */
    static final String ACTIVITY = "/api/v1/activity";
    static final String[] PUBLIC_GET = {"/api/v1/configuration/public", "/api/v1/zones", "/api/v1/meals", "/api/v1/meals/*",
            "/api/v1/kitchens/*", "/api/v1/kitchens/*/slots", "/api/v1/kitchens/*/reviews", "/api/v1/policies/*"};

    @Bean
    JwtDecoder jwtDecoder(IdentityProperties properties, Clock clock) {
        NimbusJwtDecoder decoder = NimbusJwtDecoder.withJwkSetUri(properties.backchannel("certs")).build();
        JwtTimestampValidator timestamps = new JwtTimestampValidator();
        timestamps.setClock(clock);
        decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(timestamps,
                new JwtIssuerValidator(properties.issuer()), audience(properties.apiAudience())));
        return decoder;
    }

    private static org.springframework.security.oauth2.core.OAuth2TokenValidator<Jwt> audience(String expected) {
        OAuth2Error error = new OAuth2Error("invalid_token", "Token audience is not this API", null);
        return jwt -> jwt.getAudience() != null && jwt.getAudience().contains(expected)
                ? OAuth2TokenValidatorResult.success() : OAuth2TokenValidatorResult.failure(error);
    }

    @Bean
    ClientRegistrationRepository clientRegistrations(IdentityProperties properties, MatbakhyProperties platform) {
        boolean deployed = platform.environment().deployed();
        if (deployed && (properties.webClientSecret() == null || properties.webClientSecret().isBlank())) {
            throw new IllegalStateException("OIDC_WEB_CLIENT_SECRET is required in " + platform.environment());
        }
        ClientRegistration web = ClientRegistration.withRegistrationId(REGISTRATION_ID)
                .clientId(properties.webClientId())
                .clientSecret(properties.webClientSecret() == null ? "" : properties.webClientSecret())
                .clientAuthenticationMethod(ClientAuthenticationMethod.CLIENT_SECRET_BASIC)
                .authorizationGrantType(AuthorizationGrantType.AUTHORIZATION_CODE)
                .redirectUri("{baseUrl}/login/oauth2/code/{registrationId}")
                .scope("openid", "profile", "email")
                .authorizationUri(properties.endpoint("auth"))
                .tokenUri(properties.backchannel("token"))
                .jwkSetUri(properties.backchannel("certs"))
                .userInfoUri(properties.backchannel("userinfo"))
                .userNameAttributeName("sub")
                .issuerUri(properties.issuer())
                .providerConfigurationMetadata(Map.of("end_session_endpoint", properties.endpoint("logout")))
                .build();
        return new InMemoryClientRegistrationRepository(web);
    }

    @Bean
    OidcIdTokenDecoderFactory idTokenDecoderFactory(Clock clock) {
        OidcIdTokenDecoderFactory factory = new OidcIdTokenDecoderFactory();
        factory.setJwtValidatorFactory(registration -> {
            JwtTimestampValidator timestamps = new JwtTimestampValidator();
            timestamps.setClock(clock);
            return new DelegatingOAuth2TokenValidator<>(timestamps,
                    new org.springframework.security.oauth2.client.oidc.authentication.OidcIdTokenValidator(registration));
        });
        return factory;
    }

    @Bean
    CookieSerializer sessionCookie(MatbakhyProperties platform) {
        DefaultCookieSerializer cookie = new DefaultCookieSerializer();
        cookie.setCookieName("MATBAKHY_SESSION");
        cookie.setUseHttpOnlyCookie(true);
        cookie.setSameSite("Lax");
        cookie.setCookiePath("/");
        DeploymentEnvironment env = platform.environment();
        cookie.setUseSecureCookie(env.deployed());
        return cookie;
    }

    @Bean
    CorsConfigurationSource corsConfigurationSource(IdentityProperties properties) {
        CorsConfiguration cors = new CorsConfiguration();
        cors.setAllowedOrigins(properties.allowedOrigins());
        cors.setAllowedMethods(List.of("GET", "POST", "PUT", "PATCH", "DELETE"));
        cors.setAllowedHeaders(List.of("Content-Type", "X-XSRF-TOKEN", "Idempotency-Key", "If-Match", "X-Request-Id", "Authorization"));
        cors.setExposedHeaders(List.of("X-Request-Id", "Location"));
        cors.setAllowCredentials(true);
        cors.setMaxAge(600L);
        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
        source.registerCorsConfiguration("/api/**", cors);
        return source;
    }

    @Bean
    @Order(1)
    SecurityFilterChain bearerChain(HttpSecurity http, AccountMapper mapper, ApiSecurityErrors errors) throws Exception {
        http.securityMatcher(request -> {
                    String header = request.getHeader("Authorization");
                    return header != null && header.regionMatches(true, 0, "Bearer ", 0, 7);
                })
                .cors(cors -> { })
                .csrf(csrf -> csrf.disable()) // bearer credentials are never sent ambiently by a browser
                .sessionManagement(s -> s.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers(HttpMethod.GET, PUBLIC_GET).permitAll()
                        .requestMatchers(HttpMethod.POST, ACTIVITY).permitAll()
                        .requestMatchers(HttpMethod.POST, DELETION_REQUEST).hasAnyAuthority(AccountMapper.ACTIVE, AccountMapper.DELETION_REQUESTED)
                        .requestMatchers("/api/**").hasAuthority(AccountMapper.ACTIVE)
                        .anyRequest().denyAll())
                .oauth2ResourceServer(rs -> rs
                        .jwt(jwt -> jwt.jwtAuthenticationConverter(token -> mapper.map(
                                token.getIssuer().toString(), token.getSubject(), token.getClaims())))
                        .authenticationEntryPoint(errors)
                        .accessDeniedHandler(errors))
                .exceptionHandling(e -> e.authenticationEntryPoint(errors).accessDeniedHandler(errors));
        return http.build();
    }

    /**
     * The readable XSRF-TOKEN cookie (the web apps copy it into X-XSRF-TOKEN). On a deployment with sibling hosts it is set for the
     * parent domain (WEB_COOKIE_DOMAIN), otherwise only the API host could read it and every browser mutation would be refused.
     */
    static org.springframework.security.web.csrf.CookieCsrfTokenRepository csrfTokenRepository(IdentityProperties properties) {
        org.springframework.security.web.csrf.CookieCsrfTokenRepository repository =
                org.springframework.security.web.csrf.CookieCsrfTokenRepository.withHttpOnlyFalse();
        String domain = properties.webCookieDomain();
        if (domain != null && !domain.isBlank()) {
            repository.setCookieCustomizer(cookie -> cookie.domain(domain.strip()));
        }
        return repository;
    }

    @Bean
    @Order(2)
    SecurityFilterChain webChain(HttpSecurity http, AccountMapper mapper, ApiSecurityErrors errors,
                                 IdentityProperties properties, ClientRegistrationRepository registrations) throws Exception {
        http.cors(cors -> { })
                // MB-054: the activity endpoint acts for nobody and ignores identity, so a signed-out phone (no cookie, no CSRF token)
                // can send it; every other browser request keeps CSRF protection.
                .csrf(csrf -> {
                    csrf.spa();
                    csrf.csrfTokenRepository(csrfTokenRepository(properties));
                    csrf.ignoringRequestMatchers(ACTIVITY);
                })
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers("/actuator/health", "/actuator/health/**", "/error").permitAll()
                        .requestMatchers(SecurityConfiguration::managementScrape).permitAll()
                        .requestMatchers("/oauth2/authorization/**", "/login/oauth2/code/**").permitAll()
                        .requestMatchers(HttpMethod.GET, PUBLIC_GET).permitAll()
                        .requestMatchers(HttpMethod.POST, ACTIVITY).permitAll()
                        .requestMatchers(HttpMethod.POST, DELETION_REQUEST).hasAnyAuthority(AccountMapper.ACTIVE, AccountMapper.DELETION_REQUESTED)
                        .requestMatchers("/api/**").hasAuthority(AccountMapper.ACTIVE)
                        .anyRequest().denyAll())
                .oauth2Login(login -> login
                        .authorizationEndpoint(endpoint -> endpoint.authorizationRequestResolver(stepUpResolver(registrations, properties)))
                        .successHandler(WebReturnTo.successHandler(properties.postLoginRedirect())))
                .logout(logout -> logout
                        .logoutUrl("/api/v1/auth/logout")
                        .logoutSuccessHandler(idpLogout(properties, registrations))
                        .invalidateHttpSession(true)
                        .deleteCookies("MATBAKHY_SESSION"))
                .exceptionHandling(e -> e.authenticationEntryPoint(errors).accessDeniedHandler(errors))
                .addFilterBefore(new WebAccountFilter(mapper), AuthorizationFilter.class)
                .addFilterBefore(WebReturnTo.capture(properties.allowedOrigins()),
                        org.springframework.security.oauth2.client.web.OAuth2AuthorizationRequestRedirectFilter.class);
        return http.build();
    }

    /**
     * MB-039: the Prometheus scrape is open only on a separate management port (management.server.port), served by the
     * management child context, which no proxy forwards. On the API port the endpoint is neither exposed nor permitted.
     */
    static boolean managementScrape(jakarta.servlet.http.HttpServletRequest request) {
        if (!"/actuator/prometheus".equals(request.getRequestURI())) {
            return false;
        }
        var context = org.springframework.web.context.support.WebApplicationContextUtils.findWebApplicationContext(request.getServletContext());
        return context instanceof org.springframework.boot.web.server.context.WebServerApplicationContext server
                && org.springframework.boot.web.server.context.WebServerApplicationContext.hasServerNamespace(server, "management");
    }

    /**
     * Web step-up: {@code /oauth2/authorization/keycloak?stepUp=true} asks the provider for an MFA-level ACR and a fresh
     * authentication (max_age=0). The API still decides from the returned token's acr/auth_time (StaffAssurance); this
     * only lets staff obtain such a token from the web app.
     */
    private static org.springframework.security.oauth2.client.web.OAuth2AuthorizationRequestResolver stepUpResolver(
            ClientRegistrationRepository registrations, IdentityProperties properties) {
        var defaults = new org.springframework.security.oauth2.client.web.DefaultOAuth2AuthorizationRequestResolver(registrations,
                "/oauth2/authorization");
        return new org.springframework.security.oauth2.client.web.OAuth2AuthorizationRequestResolver() {
            @Override
            public org.springframework.security.oauth2.core.endpoint.OAuth2AuthorizationRequest resolve(jakarta.servlet.http.HttpServletRequest request) {
                return stepUp(request, defaults.resolve(request));
            }

            @Override
            public org.springframework.security.oauth2.core.endpoint.OAuth2AuthorizationRequest resolve(jakarta.servlet.http.HttpServletRequest request,
                                                                                                       String registrationId) {
                return stepUp(request, defaults.resolve(request, registrationId));
            }

            private org.springframework.security.oauth2.core.endpoint.OAuth2AuthorizationRequest stepUp(jakarta.servlet.http.HttpServletRequest request,
                    org.springframework.security.oauth2.core.endpoint.OAuth2AuthorizationRequest resolved) {
                if (resolved == null || !"true".equals(request.getParameter("stepUp"))) {
                    return resolved;
                }
                return org.springframework.security.oauth2.core.endpoint.OAuth2AuthorizationRequest.from(resolved)
                        .additionalParameters(p -> {
                            p.put("acr_values", String.join(" ", properties.mfaAcrValues()));
                            p.put("max_age", "0");
                        }).build();
            }
        };
    }

    /** Responds 200 with the provider end-session URL so the web app can also end the IdP session. */
    private static LogoutSuccessHandler idpLogout(IdentityProperties properties, ClientRegistrationRepository registrations) {
        return (request, response, authentication) -> {
            String url = null;
            if (authentication instanceof OAuth2AuthenticationToken token && token.getPrincipal() instanceof OidcUser user) {
                ClientRegistration registration = ((InMemoryClientRegistrationRepository) registrations).findByRegistrationId(REGISTRATION_ID);
                url = UriComponentsBuilder.fromUriString(properties.endpoint("logout"))
                        .queryParam("client_id", registration.getClientId())
                        .queryParam("id_token_hint", user.getIdToken().getTokenValue())
                        .queryParam("post_logout_redirect_uri", properties.postLoginRedirect())
                        .encode().build().toUriString();
            }
            response.setStatus(200);
            response.setContentType("application/json");
            response.getOutputStream().write(("{\"idpLogoutUrl\":" + (url == null ? "null" : "\"" + url + "\"") + "}")
                    .getBytes(StandardCharsets.UTF_8));
        };
    }
}
package com.matbakhy.finance.internal;

import com.matbakhy.cooks.api.KitchenDirectory;
import com.matbakhy.operations.api.AuditLog;
import com.matbakhy.operations.api.AuditLog.Entry;
import com.matbakhy.operations.api.AuditLog.Outcome;
import com.matbakhy.shared.error.ApiException;
import com.matbakhy.shared.error.ApiException.FieldError;
import com.matbakhy.shared.error.ErrorCode;
import com.matbakhy.shared.idempotency.IdempotentCommands;
import java.nio.charset.StandardCharsets;
import java.sql.Timestamp;
import java.time.Clock;
import java.time.Instant;
import java.util.Base64;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Cash collection (BR-032): order completion and payment are independent. The cook declares what was collected for a
 * completed order; finance verifies or disputes it separately. A short or zero report is an exception (DISPUTED), never
 * a success. The reporter can never verify their own report.
 */
@Service
public class CashService {

    public enum Decision { VERIFY, DISPUTE }

    public record ReportInput(long amountMinor, String currency, Instant collectedAt, String method, String externalReference,
                              long expectedVersion) {
    }

    public record VerificationInput(UUID reportId, Decision decision, Long verifiedAmountMinor, String reference, String reason,
                                    long expectedVersion) {
    }

    public record Money(long amountMinor, String currency) {
    }

    public record CashReportView(UUID id, Money amount, Instant collectedAt, String externalReference, Instant reportedAt, Money discrepancy,
                                 String state, Money verifiedAmount, String verificationReference, Instant verifiedAt, long version) {
    }

    /** One order's cash position: what is due and, only if they exist, the cook's report and finance's verification. */
    public record CashItem(UUID orderId, String publicNumber, UUID kitchenId, String orderState, Money amountDue, String cashState,
                           CashReportView report) {
    }

    public record CashPage(List<CashItem> items, String nextCursor, boolean hasMore) {
    }

    private final JdbcTemplate jdbc;
    private final KitchenDirectory kitchens;
    private final IdempotentCommands idempotency;
    private final AuditLog audit;
    private final Clock clock;

    CashService(JdbcTemplate jdbc, KitchenDirectory kitchens, IdempotentCommands idempotency, AuditLog audit, Clock clock) {
        this.jdbc = jdbc;
        this.kitchens = kitchens;
        this.idempotency = idempotency;
        this.audit = audit;
        this.clock = clock;
    }

    @Transactional
    public CashReportView report(UUID cookId, String key, UUID orderId, ReportInput in) {
        UUID kitchen = kitchens.ownedBy(cookId).map(KitchenDirectory.KitchenStatus::kitchenId)
                .orElseThrow(() -> new ApiException(ErrorCode.FORBIDDEN, "not a cook"));
        UUID reportId = idempotency.execute(cookId, "cash.report", key, Map.of("orderId", orderId.toString(), "input", in), UUID.class, () -> {
            Map<String, Object> o = jdbc.queryForList("""
                    SELECT o.state, o.version, o.total_minor, o.created_at, c.state AS cash_state FROM customer_order o
                    JOIN cash_obligation c ON c.order_id = o.id WHERE o.id = ? AND o.kitchen_id = ? FOR UPDATE OF c""", orderId, kitchen)
                    .stream().findFirst().orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "order not found"));
            if (in.expectedVersion() != (Long) o.get("version")) {
                throw new ApiException(ErrorCode.VERSION_CONFLICT, "stale order version");
            }
            if (!"COMPLETED".equals(o.get("state"))) {
                throw new ApiException(ErrorCode.STATE_CONFLICT, "cash is reported after handover", List.of(new FieldError("state", (String) o.get("state"))));
            }
            if (!"DUE".equals(o.get("cash_state"))) {
                throw new ApiException(ErrorCode.STATE_CONFLICT, "cash already reported", List.of(new FieldError("cashState", (String) o.get("cash_state"))));
            }
            if (!"EGP".equals(in.currency()) || !"CASH".equals(in.method())) {
                throw invalid("method", "CASH_EGP_ONLY");
            }
            Instant now = clock.instant();
            if (in.collectedAt() == null || in.collectedAt().isAfter(now) || in.collectedAt().isBefore(((Timestamp) o.get("created_at")).toInstant())) {
                throw invalid("collectedAt", "BETWEEN_ORDER_AND_NOW");
            }
            long due = (Long) o.get("total_minor");
            long discrepancy = Math.subtractExact(in.amountMinor(), due);
            UUID id = UUID.randomUUID();
            String reference = in.externalReference() == null || in.externalReference().isBlank() ? null : in.externalReference().strip();
            jdbc.update("""
                    INSERT INTO cash_report (id, order_id, reporter_id, amount_minor, collected_at, external_reference, reported_at, discrepancy_minor, state)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'REPORTED')""",
                    id, orderId, cookId, in.amountMinor(), Timestamp.from(in.collectedAt()), reference, Timestamp.from(now), discrepancy);
            // An exact report awaits verification; any difference is an exception for finance, not a success.
            jdbc.update("UPDATE cash_obligation SET state = ?, version = version + 1 WHERE order_id = ? AND state = 'DUE'",
                    discrepancy == 0 ? "REPORTED" : "DISPUTED", orderId);
            return id;
        });
        return view(reportId);
    }

    /** Refuses (and audits) a reporter verifying their own report; separate so the denial audit survives. */
    @Transactional(noRollbackFor = ApiException.class)
    public void refuseSelfVerification(UUID staffId, UUID reportId, String requestId) {
        UUID reporter = jdbc.query("SELECT reporter_id FROM cash_report WHERE id = ?", rs -> rs.next() ? rs.getObject(1, UUID.class) : null, reportId);
        if (staffId.equals(reporter)) {
            audit.record(new Entry(staffId, "cash.verify", "finance.verify", "cash_report", reportId.toString(), Outcome.DENIED,
                    "reporter cannot verify own report", requestId, Map.of()));
            throw new ApiException(ErrorCode.FORBIDDEN, "separation of duties");
        }
    }

    @Transactional
    public CashReportView verify(UUID staffId, String key, VerificationInput in, String requestId) {
        UUID reportId = idempotency.execute(staffId, "cash.verify", key, in, UUID.class, () -> {
            Map<String, Object> r = jdbc.queryForList("""
                    SELECT r.order_id, r.reporter_id, r.state, r.version, r.discrepancy_minor, o.total_minor FROM cash_report r
                    JOIN customer_order o ON o.id = r.order_id WHERE r.id = ? FOR UPDATE OF r""", in.reportId()).stream().findFirst()
                    .orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "cash report not found"));
            if (staffId.equals(r.get("reporter_id"))) {
                throw new ApiException(ErrorCode.FORBIDDEN, "separation of duties");
            }
            if (in.expectedVersion() != (Long) r.get("version")) {
                throw new ApiException(ErrorCode.VERSION_CONFLICT, "stale cash report version");
            }
            if (!"REPORTED".equals(r.get("state"))) {
                throw new ApiException(ErrorCode.STATE_CONFLICT, "report already decided", List.of(new FieldError("state", (String) r.get("state"))));
            }
            long due = (Long) r.get("total_minor");
            String reason = in.reason() == null ? null : in.reason().strip();
            if (in.verifiedAmountMinor() == null || in.verifiedAmountMinor() < 0) {
                throw invalid("verifiedAmountMinor", "REQUIRED");
            }
            boolean exceptional = (Long) r.get("discrepancy_minor") != 0 || in.decision() == Decision.DISPUTE;
            if (exceptional && (reason == null || reason.length() < 3)) {
                throw invalid("reason", "REQUIRED_FOR_EXCEPTIONS");
            }
            if (in.decision() == Decision.VERIFY && in.verifiedAmountMinor() != due) {
                // Verification confirms full collection; any other amount must be recorded as a dispute.
                throw invalid("verifiedAmountMinor", "MUST_EQUAL_AMOUNT_DUE_OR_DISPUTE");
            }
            String outcome = in.decision() == Decision.VERIFY ? "VERIFIED" : "DISPUTED";
            Instant now = clock.instant();
            jdbc.update("""
                    UPDATE cash_report SET state = ?, verified_by = ?, verified_amount_minor = ?, verification_reference = ?, verification_reason = ?,
                           verified_at = ?, version = version + 1 WHERE id = ?""",
                    outcome, staffId, in.verifiedAmountMinor(), in.reference() == null || in.reference().isBlank() ? null : in.reference().strip(),
                    reason, Timestamp.from(now), in.reportId());
            jdbc.update("UPDATE cash_obligation SET state = ?, version = version + 1 WHERE order_id = ?", outcome, r.get("order_id"));
            audit.record(new Entry(staffId, "cash.verify", "finance.verify", "cash_report", in.reportId().toString(), Outcome.ALLOWED,
                    reason == null ? outcome : reason, requestId, Map.of("decision", in.decision().name(), "verifiedAmountMinor", in.verifiedAmountMinor())));
            return in.reportId();
        });
        return view(reportId);
    }

    public CashPage list(String state, UUID kitchenId, String cursor, int limit) {
        if (state != null && !Set.of("DUE", "REPORTED", "VERIFIED", "DISPUTED", "NOT_DUE").contains(state)) {
            throw invalid("state", "UNKNOWN_STATE");
        }
        if (limit < 1 || limit > 100) {
            throw invalid("limit", "RANGE_1_100");
        }
        Instant afterTime = Instant.EPOCH;
        UUID afterId = new UUID(0, 0);
        if (cursor != null) {
            try {
                String[] parts = new String(Base64.getUrlDecoder().decode(cursor), StandardCharsets.UTF_8).split("\\|", 2);
                afterTime = Instant.parse(parts[0]);
                afterId = UUID.fromString(parts[1]);
            } catch (RuntimeException e) {
                throw invalid("cursor", "INVALID");
            }
        }
        List<Map<String, Object>> rows = jdbc.queryForList("""
                SELECT o.id, o.public_number, o.kitchen_id, o.state AS order_state, c.amount_minor, c.state AS cash_state, c.created_at,
                       r.id AS report_id
                FROM cash_obligation c JOIN customer_order o ON o.id = c.order_id LEFT JOIN cash_report r ON r.order_id = o.id
                WHERE (?::text IS NULL OR c.state = ?) AND (?::uuid IS NULL OR o.kitchen_id = ?) AND (c.created_at, o.id) > (?, ?)
                ORDER BY c.created_at, o.id LIMIT ?""",
                state, state, kitchenId, kitchenId, Timestamp.from(afterTime), afterId, limit + 1);
        boolean more = rows.size() > limit;
        List<Map<String, Object>> page = more ? rows.subList(0, limit) : rows;
        List<CashItem> items = page.stream().map(row -> new CashItem((UUID) row.get("id"), (String) row.get("public_number"),
                (UUID) row.get("kitchen_id"), (String) row.get("order_state"), egp((Long) row.get("amount_minor")), (String) row.get("cash_state"),
                row.get("report_id") == null ? null : view((UUID) row.get("report_id")))).toList();
        String next = null;
        if (more) {
            Map<String, Object> last = page.getLast();
            next = Base64.getUrlEncoder().withoutPadding().encodeToString((((Timestamp) last.get("created_at")).toInstant() + "|" + last.get("id"))
                    .getBytes(StandardCharsets.UTF_8));
        }
        return new CashPage(items, next, more);
    }

    private CashReportView view(UUID reportId) {
        return jdbc.query("SELECT * FROM cash_report WHERE id = ?", (rs, n) -> new CashReportView(rs.getObject("id", UUID.class),
                egp(rs.getLong("amount_minor")), rs.getTimestamp("collected_at").toInstant(), rs.getString("external_reference"),
                rs.getTimestamp("reported_at").toInstant(), egp(rs.getLong("discrepancy_minor")), rs.getString("state"),
                rs.getObject("verified_amount_minor") == null ? null : egp(rs.getLong("verified_amount_minor")), rs.getString("verification_reference"),
                rs.getTimestamp("verified_at") == null ? null : rs.getTimestamp("verified_at").toInstant(), rs.getLong("version")), reportId).getFirst();
    }

    private static Money egp(long minor) {
        return new Money(minor, "EGP");
    }

    private static ApiException invalid(String field, String code) {
        return new ApiException(ErrorCode.VALIDATION_FAILED, "invalid " + field, List.of(new FieldError(field, code)));
    }
}
package com.matbakhy.app.idempotency;

import com.matbakhy.shared.error.ApiException;
import com.matbakhy.shared.error.ErrorCode;
import com.matbakhy.shared.idempotency.IdempotentCommands;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.sql.Timestamp;
import java.time.Clock;
import java.time.Duration;
import java.util.HexFormat;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.function.Supplier;
import java.util.regex.Pattern;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.json.JsonMapper;

/**
 * PostgreSQL-backed idempotency. The insert of the scope row blocks on a concurrent uncommitted insert of
 * the same scope, so two racing requests with one key execute the command once; the loser then reads the
 * committed result (or retries the command if the winner rolled back).
 */
@Component
class JdbcIdempotentCommands implements IdempotentCommands {

    static final Duration RETENTION = Duration.ofHours(24);
    private static final Pattern KEY = Pattern.compile("[A-Za-z0-9-]{8,128}");

    private final JdbcTemplate jdbc;
    private final JsonMapper json;
    private final Clock clock;

    JdbcIdempotentCommands(JdbcTemplate jdbc, JsonMapper json, Clock clock) {
        this.jdbc = jdbc;
        this.json = json;
        this.clock = clock;
    }

    @Override
    // Business failures (ApiException) leave the rollback decision to the caller's transaction, so a caller can keep
    // deliberate writes such as counted failed attempts; any other failure marks the transaction for rollback.
    @Transactional(propagation = Propagation.MANDATORY, noRollbackFor = ApiException.class)
    public <T> T execute(UUID actorId, String command, String idempotencyKey, Object request, Class<T> resultType, Supplier<T> action) {
        if (idempotencyKey == null || !KEY.matcher(idempotencyKey).matches()) {
            throw new ApiException(ErrorCode.MALFORMED_REQUEST, "Idempotency-Key missing or malformed",
                    List.of(new ApiException.FieldError("Idempotency-Key", "REQUIRED")));
        }
        String hash = sha256(json.writeValueAsString(request));
        Timestamp now = Timestamp.from(clock.instant());
        int inserted = jdbc.update("""
                INSERT INTO idempotency_record (actor_id, command, idempotency_key, request_hash, created_at, expires_at)
                VALUES (?, ?, ?, ?, ?, ?) ON CONFLICT DO NOTHING""",
                actorId, command, idempotencyKey, hash, now, Timestamp.from(now.toInstant().plus(RETENTION)));
        if (inserted == 0) {
            List<Map<String, Object>> rows = jdbc.queryForList("""
                    SELECT request_hash, response_snapshot::text AS snapshot FROM idempotency_record
                    WHERE actor_id = ? AND command = ? AND idempotency_key = ? FOR UPDATE""", actorId, command, idempotencyKey);
            if (rows.isEmpty()) {
                throw new ApiException(ErrorCode.IDEMPOTENCY_CONFLICT, "idempotency record vanished");
            }
            if (!hash.equals(rows.getFirst().get("request_hash"))) {
                throw new ApiException(ErrorCode.IDEMPOTENCY_CONFLICT, "Idempotency-Key reused with a different request");
            }
            Object snapshot = rows.getFirst().get("snapshot");
            if (snapshot == null) {
                throw new ApiException(ErrorCode.IDEMPOTENCY_CONFLICT, "original request has no stored result");
            }
            return json.readValue(snapshot.toString(), resultType);
        }
        T result;
        try {
            result = action.get();
        } catch (RuntimeException failure) {
            // A failed command stores no outcome, even if the caller's transaction does not roll back. If the database
            // already aborted the transaction the rollback removes the record anyway; the original failure is kept.
            try {
                jdbc.update("DELETE FROM idempotency_record WHERE actor_id = ? AND command = ? AND idempotency_key = ?",
                        actorId, command, idempotencyKey);
            } catch (RuntimeException cleanup) {
                failure.addSuppressed(cleanup);
            }
            throw failure;
        }
        jdbc.update("""
                UPDATE idempotency_record SET result_status = 200, response_snapshot = ?::jsonb
                WHERE actor_id = ? AND command = ? AND idempotency_key = ?""",
                json.writeValueAsString(result), actorId, command, idempotencyKey);
        return result;
    }

    private static String sha256(String value) {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}

package com.matbakhy.finance.internal;

import java.sql.Timestamp;
import java.time.Clock;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Commission ledger (BR-033). A completed order owes the platform its commission snapshot (rate taken at placement,
 * on the subtotal only, delivery excluded, rounded half up): one balanced, immutable group per completion event —
 * debit the cook's commission receivable, credit platform commission revenue. Delivering the event again posts
 * nothing (unique source event); later policy changes cannot alter it.
 */
@Service
public class LedgerService {

    private final JdbcTemplate jdbc;
    private final Clock clock;

    LedgerService(JdbcTemplate jdbc, Clock clock) {
        this.jdbc = jdbc;
        this.clock = clock;
    }

    /** Returns true when this call posted the group, false when the source event was already posted. */
    @Transactional
    public boolean postCommission(UUID sourceEventId, UUID orderId) {
        Map<String, Object> o = jdbc.queryForList("""
                SELECT o.kitchen_id, o.subtotal_minor, o.commission_bps_snapshot, o.commission_minor, o.state, e.to_state AS event_state
                FROM customer_order o JOIN order_event e ON e.order_id = o.id AND e.id = ? WHERE o.id = ?""", sourceEventId, orderId)
                .stream().findFirst().orElseThrow(() -> new IllegalArgumentException("unknown completion event " + sourceEventId));
        if (!"COMPLETED".equals(o.get("event_state"))) {
            throw new IllegalArgumentException("commission posts only for completion events");
        }
        UUID group = UUID.randomUUID();
        int inserted = jdbc.update("""
                INSERT INTO ledger_group (id, source_event_id, kind, order_id, kitchen_id, rate_bps, base_minor, posted_at)
                VALUES (?, ?, 'COMMISSION', ?, ?, ?, ?, ?) ON CONFLICT (kind, source_event_id) DO NOTHING""",
                group, sourceEventId, orderId, o.get("kitchen_id"), o.get("commission_bps_snapshot"), o.get("subtotal_minor"),
                Timestamp.from(clock.instant()));
        if (inserted == 0) {
            return false;
        }
        long amount = (Long) o.get("commission_minor");
        jdbc.update("INSERT INTO ledger_entry (id, group_id, account, direction, amount_minor) VALUES (?, ?, 'COOK_COMMISSION_RECEIVABLE', 'DEBIT', ?)",
                UUID.randomUUID(), group, amount);
        jdbc.update("INSERT INTO ledger_entry (id, group_id, account, direction, amount_minor) VALUES (?, ?, 'PLATFORM_COMMISSION_REVENUE', 'CREDIT', ?)",
                UUID.randomUUID(), group, amount);
        return true;
    }

    /** Completion events not yet posted (read model over order events). */
    public List<Map<String, Object>> unpostedCompletions(int limit) {
        return jdbc.queryForList("""
                SELECT e.id AS event_id, e.order_id FROM order_event e
                WHERE e.to_state = 'COMPLETED'
                  AND NOT EXISTS (SELECT 1 FROM ledger_group g WHERE g.kind = 'COMMISSION' AND g.source_event_id = e.id)
                ORDER BY e.occurred_at LIMIT ?""", limit);
    }
}
package com.matbakhy.finance.internal;

import com.matbakhy.finance.internal.CashService.Money;
import com.matbakhy.identity.api.Permission;
import com.matbakhy.operations.api.AuditLog;
import com.matbakhy.operations.api.AuditLog.Entry;
import com.matbakhy.operations.api.AuditLog.Outcome;
import com.matbakhy.shared.error.ApiException;
import com.matbakhy.shared.error.ApiException.FieldError;
import com.matbakhy.shared.error.ErrorCode;
import com.matbakhy.shared.idempotency.IdempotentCommands;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.Clock;
import java.time.Instant;
import java.time.LocalDate;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Finance operations (BR-034..036). Cash is collected by the cook, so the platform's claim is the commission receivable,
 * never the gross order amount. A refund is a full refund of the verified collection less refunds already committed
 * (anything not rejected), so approved-but-unpaid refunds block over-refunds. A verified refund reverses the order's
 * commission once (one reversal group per refund; the full commission for a full refund is the proposed synthetic
 * policy until O04). Settlement batches collect ledger groups once each; reviewed batches are immutable; payment is
 * recorded only with an external reference and reconciled by another person. Duties are separated by database checks.
 */
@Service
public class FinanceOpsService {

    public record Refund(UUID id, UUID orderId, UUID kitchenId, String caseReference, Money amount, String state, String reason,
                         UUID requestedBy, UUID approvedBy, UUID paidBy, String paymentReference, UUID verifiedBy, String decisionReason,
                         Instant createdAt, Instant updatedAt, long version) {
    }

    public record SettlementLine(UUID ledgerGroupId, String kind, UUID orderId, Money amount) {
    }

    public record Settlement(UUID id, UUID kitchenId, LocalDate periodFrom, LocalDate periodTo, String state, Money total, String direction,
                             List<SettlementLine> lines, UUID createdBy, UUID reviewedBy, String paymentReference, UUID paymentRecordedBy,
                             UUID reconciledBy, Instant createdAt, Instant updatedAt, long version) {
    }

    private final JdbcTemplate jdbc;
    private final IdempotentCommands idempotency;
    private final AuditLog audit;
    private final Clock clock;

    FinanceOpsService(JdbcTemplate jdbc, IdempotentCommands idempotency, AuditLog audit, Clock clock) {
        this.jdbc = jdbc;
        this.idempotency = idempotency;
        this.audit = audit;
        this.clock = clock;
    }

    // ---- refunds (API-084/085) ----

    @Transactional
    public Refund requestRefund(UUID staffId, String key, UUID orderId, String caseReference, Long fullAmountMinor, String reason, String requestId) {
        UUID id = idempotency.execute(staffId, "refund.request", key, Map.of("orderId", String.valueOf(orderId), "case", String.valueOf(caseReference),
                "amount", String.valueOf(fullAmountMinor), "reason", String.valueOf(reason)), UUID.class, () -> {
            Map<String, Object> o = jdbc.queryForList("""
                    SELECT o.kitchen_id, c.state AS cash_state, r.verified_amount_minor FROM customer_order o
                    JOIN cash_obligation c ON c.order_id = o.id LEFT JOIN cash_report r ON r.order_id = o.id
                    WHERE o.id = ? FOR UPDATE OF c""", orderId).stream().findFirst()
                    .orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "order not found"));
            if (!"VERIFIED".equals(o.get("cash_state")) || o.get("verified_amount_minor") == null) {
                throw new ApiException(ErrorCode.STATE_CONFLICT, "no verified collection to refund", List.of(new FieldError("orderId", "COLLECTION_NOT_VERIFIED")));
            }
            long committed = jdbc.queryForObject("SELECT coalesce(sum(amount_minor), 0) FROM refund WHERE order_id = ? AND state <> 'REJECTED'",
                    Long.class, orderId);
            long refundable = ((Number) o.get("verified_amount_minor")).longValue() - committed;
            if (refundable <= 0) {
                throw new ApiException(ErrorCode.STATE_CONFLICT, "already refunded", List.of(new FieldError("fullAmountMinor", "OVER_REFUND")));
            }
            if (fullAmountMinor == null || fullAmountMinor != refundable) {
                throw new ApiException(ErrorCode.VALIDATION_FAILED, "full refund of " + refundable + " required",
                        List.of(new FieldError("fullAmountMinor", fullAmountMinor != null && fullAmountMinor > refundable ? "OVER_REFUND" : "FULL_REFUND_REQUIRED")));
            }
            String why = text("reason", reason, 3, 1000);
            String ref = text("caseId", caseReference, 3, 100);
            UUID refund = UUID.randomUUID();
            Instant now = clock.instant();
            jdbc.update("""
                    INSERT INTO refund (id, order_id, kitchen_id, case_reference, amount_minor, state, reason, requested_by, created_at, updated_at)
                    VALUES (?, ?, ?, ?, ?, 'REQUESTED', ?, ?, ?, ?)""", refund, orderId, o.get("kitchen_id"), ref, fullAmountMinor, why, staffId,
                    Timestamp.from(now), Timestamp.from(now));
            audit.record(new Entry(staffId, "refund.request", Permission.FINANCE_REFUND_APPROVE.code(), "refund", refund.toString(), Outcome.ALLOWED, why,
                    requestId, Map.of("orderId", orderId.toString(), "amountMinor", fullAmountMinor)));
            return refund;
        });
        return refund(id);
    }

    @Transactional
    public Refund refundAction(UUID staffId, String key, UUID refundId, String action, Long expectedVersion, String evidenceRef, String reason,
                               String requestId) {
        UUID id = idempotency.execute(staffId, "refund.action", key, Map.of("refundId", refundId.toString(), "action", String.valueOf(action),
                "expectedVersion", String.valueOf(expectedVersion), "evidence", String.valueOf(evidenceRef)), UUID.class, () -> {
            Refund r = jdbc.query("SELECT * FROM refund WHERE id = ? FOR UPDATE", FinanceOpsService::mapRefund, refundId).stream().findFirst()
                    .orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "refund not found"));
            if (expectedVersion == null || expectedVersion != r.version()) {
                throw new ApiException(ErrorCode.VERSION_CONFLICT, "stale refund version");
            }
            Instant now = clock.instant();
            switch (String.valueOf(action)) {
                case "APPROVE" -> {
                    requireState(r.state(), "REQUESTED");
                    separate(staffId, r.requestedBy());
                    jdbc.update("UPDATE refund SET state = 'APPROVED', approved_by = ?, updated_at = ?, version = version + 1 WHERE id = ?", staffId,
                            Timestamp.from(now), refundId);
                }
                case "REJECT" -> {
                    if (!Set.of("REQUESTED", "APPROVED").contains(r.state())) {
                        throw conflict(r.state());
                    }
                    jdbc.update("UPDATE refund SET state = 'REJECTED', decision_reason = ?, updated_at = ?, version = version + 1 WHERE id = ?",
                            text("reason", reason, 3, 1000), Timestamp.from(now), refundId);
                }
                case "PAYMENT_RECORDED" -> {
                    requireState(r.state(), "APPROVED");
                    jdbc.update("UPDATE refund SET state = 'PAID', paid_by = ?, payment_reference = ?, updated_at = ?, version = version + 1 WHERE id = ?",
                            staffId, text("evidenceRef", evidenceRef, 3, 200), Timestamp.from(now), refundId);
                }
                case "VERIFY" -> {
                    requireState(r.state(), "PAID");
                    separate(staffId, r.paidBy());
                    reverseCommission(refundId, r.orderId());
                    jdbc.update("UPDATE refund SET state = 'VERIFIED', verified_by = ?, updated_at = ?, version = version + 1 WHERE id = ?", staffId,
                            Timestamp.from(now), refundId);
                }
                default -> throw invalid("action", "APPROVE|REJECT|PAYMENT_RECORDED|VERIFY");
            }
            audit.record(new Entry(staffId, "refund." + action.toLowerCase(), Permission.FINANCE_REFUND_APPROVE.code(), "refund", refundId.toString(),
                    Outcome.ALLOWED, reason, requestId, Map.of("from", r.state())));
            return refundId;
        });
        return refund(id);
    }

    /** One reversal group per refund (unique source); the order's posted commission must exist. */
    private void reverseCommission(UUID refundId, UUID orderId) {
        Map<String, Object> g = jdbc.queryForList("""
                SELECT g.kitchen_id, g.rate_bps, g.base_minor, e.amount_minor FROM ledger_group g
                JOIN ledger_entry e ON e.group_id = g.id AND e.account = 'COOK_COMMISSION_RECEIVABLE' AND e.direction = 'DEBIT'
                WHERE g.order_id = ? AND g.kind = 'COMMISSION'""", orderId).stream().findFirst()
                .orElseThrow(() -> new ApiException(ErrorCode.STATE_CONFLICT, "commission not posted yet", List.of(new FieldError("orderId", "COMMISSION_NOT_POSTED"))));
        UUID group = UUID.randomUUID();
        int inserted = jdbc.update("""
                INSERT INTO ledger_group (id, source_event_id, kind, order_id, kitchen_id, rate_bps, base_minor, posted_at)
                VALUES (?, ?, 'COMMISSION_REVERSAL', ?, ?, ?, ?, ?) ON CONFLICT (kind, source_event_id) DO NOTHING""",
                group, refundId, orderId, g.get("kitchen_id"), g.get("rate_bps"), g.get("base_minor"), Timestamp.from(clock.instant()));
        if (inserted == 0) {
            return;
        }
        long amount = ((Number) g.get("amount_minor")).longValue();
        jdbc.update("INSERT INTO ledger_entry (id, group_id, account, direction, amount_minor) VALUES (?, ?, 'PLATFORM_COMMISSION_REVENUE', 'DEBIT', ?)",
                UUID.randomUUID(), group, amount);
        jdbc.update("INSERT INTO ledger_entry (id, group_id, account, direction, amount_minor) VALUES (?, ?, 'COOK_COMMISSION_RECEIVABLE', 'CREDIT', ?)",
                UUID.randomUUID(), group, amount);
    }

    public Refund refund(UUID id) {
        return jdbc.query("SELECT * FROM refund WHERE id = ?", FinanceOpsService::mapRefund, id).stream().findFirst()
                .orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "refund not found"));
    }

    public List<Refund> refunds(String state, UUID orderId) {
        return jdbc.query("SELECT * FROM refund WHERE (?::text IS NULL OR state = ?) AND (?::uuid IS NULL OR order_id = ?) ORDER BY created_at DESC, id LIMIT 200",
                FinanceOpsService::mapRefund, state, state, orderId, orderId);
    }

    // ---- settlements (API-087/088) ----

    @Transactional
    public Settlement createSettlement(UUID staffId, String key, UUID kitchenId, LocalDate from, LocalDate to, List<UUID> entryIds, String requestId) {
        UUID id = idempotency.execute(staffId, "settlement.create", key, Map.of("kitchenId", String.valueOf(kitchenId), "from", String.valueOf(from),
                "to", String.valueOf(to), "entries", String.valueOf(entryIds)), UUID.class, () -> {
            if (kitchenId == null || from == null || to == null || to.isBefore(from)) {
                throw invalid("period", "VALID_PERIOD_REQUIRED");
            }
            if (entryIds == null || entryIds.isEmpty() || entryIds.size() > 500) {
                throw invalid("entryIds", "SIZE_1_500");
            }
            Set<UUID> unique = new LinkedHashSet<>(entryIds);
            UUID batch = UUID.randomUUID();
            Instant now = clock.instant();
            jdbc.update("""
                    INSERT INTO settlement_batch (id, kitchen_id, period_from, period_to, state, total_minor, created_by, created_at, updated_at)
                    VALUES (?, ?, ?, ?, 'DRAFT', 0, ?, ?, ?)""", batch, kitchenId, from, to, staffId, Timestamp.from(now), Timestamp.from(now));
            long total = 0;
            for (UUID entry : unique) {
                Map<String, Object> g = jdbc.queryForList("""
                        SELECT g.kind, g.kitchen_id, g.posted_at, e.amount_minor FROM ledger_group g
                        JOIN ledger_entry e ON e.group_id = g.id AND e.account = 'COOK_COMMISSION_RECEIVABLE'
                        WHERE g.id = ?""", entry).stream().findFirst()
                        .orElseThrow(() -> invalid("entryIds", "UNKNOWN_ENTRY"));
                if (!kitchenId.equals(g.get("kitchen_id"))) {
                    throw invalid("entryIds", "OTHER_KITCHEN");
                }
                LocalDate posted = LocalDate.ofInstant(((Timestamp) g.get("posted_at")).toInstant(), StatementService.CAIRO);
                if (posted.isBefore(from) || posted.isAfter(to)) {
                    throw invalid("entryIds", "OUTSIDE_PERIOD");
                }
                long amount = ((Number) g.get("amount_minor")).longValue() * ("COMMISSION".equals(g.get("kind")) ? 1 : -1);
                if (amount == 0) {
                    // MB-050 (D10): a zero-commission group has nothing to settle.
                    throw invalid("entryIds", "ZERO_AMOUNT");
                }
                try {
                    jdbc.update("INSERT INTO settlement_line (batch_id, ledger_group_id, amount_minor) VALUES (?, ?, ?)", batch, entry, amount);
                } catch (DuplicateKeyException e) {
                    throw new ApiException(ErrorCode.STATE_CONFLICT, "entry already in a settlement", List.of(new FieldError("entryIds", "ALREADY_SETTLED")));
                }
                total += amount;
            }
            jdbc.update("UPDATE settlement_batch SET total_minor = ? WHERE id = ?", total, batch);
            audit.record(new Entry(staffId, "settlement.create", Permission.FINANCE_SETTLEMENT.code(), "settlement_batch", batch.toString(),
                    Outcome.ALLOWED, null, requestId, Map.of("kitchenId", kitchenId.toString(), "totalMinor", total)));
            return batch;
        });
        return settlement(id);
    }

    @Transactional
    public Settlement settlementAction(UUID staffId, String key, UUID batchId, String action, Long expectedVersion, String evidenceRef, String requestId) {
        UUID id = idempotency.execute(staffId, "settlement.action", key, Map.of("batchId", batchId.toString(), "action", String.valueOf(action),
                "expectedVersion", String.valueOf(expectedVersion), "evidence", String.valueOf(evidenceRef)), UUID.class, () -> {
            Map<String, Object> b = jdbc.queryForList("SELECT state, version, created_by, payment_recorded_by FROM settlement_batch WHERE id = ? FOR UPDATE",
                    batchId).stream().findFirst().orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "settlement not found"));
            if (expectedVersion == null || expectedVersion != (Long) b.get("version")) {
                throw new ApiException(ErrorCode.VERSION_CONFLICT, "stale settlement version");
            }
            String state = (String) b.get("state");
            Instant now = clock.instant();
            switch (String.valueOf(action)) {
                case "REVIEW" -> {
                    requireState(state, "DRAFT");
                    separate(staffId, (UUID) b.get("created_by"));
                    jdbc.update("UPDATE settlement_batch SET state = 'REVIEWED', reviewed_by = ?, updated_at = ?, version = version + 1 WHERE id = ?",
                            staffId, Timestamp.from(now), batchId);
                }
                case "PAYMENT_RECORDED" -> {
                    requireState(state, "REVIEWED");
                    jdbc.update("""
                            UPDATE settlement_batch SET state = 'PAYMENT_RECORDED', payment_reference = ?, payment_recorded_by = ?, updated_at = ?,
                                   version = version + 1 WHERE id = ?""", text("evidenceRef", evidenceRef, 3, 200), staffId, Timestamp.from(now), batchId);
                }
                case "RECONCILE" -> {
                    requireState(state, "PAYMENT_RECORDED");
                    separate(staffId, (UUID) b.get("payment_recorded_by"));
                    jdbc.update("UPDATE settlement_batch SET state = 'RECONCILED', reconciled_by = ?, updated_at = ?, version = version + 1 WHERE id = ?",
                            staffId, Timestamp.from(now), batchId);
                }
                case "CANCEL" -> {
                    // Reviewed batches are immutable; corrections are new batches with reversal entries.
                    requireState(state, "DRAFT");
                    jdbc.update("UPDATE settlement_batch SET state = 'CANCELLED', updated_at = ?, version = version + 1 WHERE id = ?",
                            Timestamp.from(now), batchId);
                    jdbc.update("UPDATE settlement_line SET active = false WHERE batch_id = ?", batchId);
                }
                default -> throw invalid("action", "REVIEW|PAYMENT_RECORDED|RECONCILE|CANCEL");
            }
            audit.record(new Entry(staffId, "settlement." + action.toLowerCase(), Permission.FINANCE_SETTLEMENT.code(), "settlement_batch", batchId.toString(),
                    Outcome.ALLOWED, evidenceRef, requestId, Map.of("from", state)));
            return batchId;
        });
        return settlement(id);
    }

    public Settlement settlement(UUID id) {
        List<SettlementLine> lines = jdbc.query("""
                SELECT l.ledger_group_id, g.kind, g.order_id, l.amount_minor FROM settlement_line l JOIN ledger_group g ON g.id = l.ledger_group_id
                WHERE l.batch_id = ? ORDER BY g.posted_at, g.id""",
                (rs, n) -> new SettlementLine(rs.getObject(1, UUID.class), rs.getString(2), rs.getObject(3, UUID.class), egp(rs.getLong(4))), id);
        return jdbc.query("SELECT * FROM settlement_batch WHERE id = ?", (rs, n) -> new Settlement(rs.getObject("id", UUID.class),
                rs.getObject("kitchen_id", UUID.class), rs.getObject("period_from", LocalDate.class), rs.getObject("period_to", LocalDate.class),
                rs.getString("state"), egp(rs.getLong("total_minor")), "COOK_PAYS_PLATFORM", lines, rs.getObject("created_by", UUID.class),
                rs.getObject("reviewed_by", UUID.class), rs.getString("payment_reference"), rs.getObject("payment_recorded_by", UUID.class),
                rs.getObject("reconciled_by", UUID.class), rs.getTimestamp("created_at").toInstant(), rs.getTimestamp("updated_at").toInstant(),
                rs.getLong("version")), id).stream().findFirst().orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "settlement not found"));
    }

    /** Ledger groups of a kitchen with a non-zero amount, not in an active settlement line, for building a batch. */
    public List<SettlementLine> unsettled(UUID kitchenId) {
        return jdbc.query("""
                SELECT g.id, g.kind, g.order_id, CASE WHEN g.kind = 'COMMISSION' THEN e.amount_minor ELSE -e.amount_minor END
                FROM ledger_group g JOIN ledger_entry e ON e.group_id = g.id AND e.account = 'COOK_COMMISSION_RECEIVABLE'
                WHERE g.kitchen_id = ? AND e.amount_minor <> 0
                  AND NOT EXISTS (SELECT 1 FROM settlement_line l WHERE l.ledger_group_id = g.id AND l.active)
                ORDER BY g.posted_at, g.id LIMIT 500""",
                (rs, n) -> new SettlementLine(rs.getObject(1, UUID.class), rs.getString(2), rs.getObject(3, UUID.class), egp(rs.getLong(4))), kitchenId);
    }

    // ---- helpers ----

    /** Separation of duties (also enforced by database checks). */
    private static void separate(UUID actor, UUID other) {
        if (actor.equals(other)) {
            throw new ApiException(ErrorCode.FORBIDDEN, "separation of duties: the same person cannot do both steps");
        }
    }

    private static void requireState(String actual, String expected) {
        if (!expected.equals(actual)) {
            throw conflict(actual);
        }
    }

    private static ApiException conflict(String state) {
        return new ApiException(ErrorCode.STATE_CONFLICT, "not allowed from " + state, List.of(new FieldError("state", state)));
    }

    private static Refund mapRefund(ResultSet rs, int n) throws SQLException {
        return new Refund(rs.getObject("id", UUID.class), rs.getObject("order_id", UUID.class), rs.getObject("kitchen_id", UUID.class),
                rs.getString("case_reference"), egp(rs.getLong("amount_minor")), rs.getString("state"), rs.getString("reason"),
                rs.getObject("requested_by", UUID.class), rs.getObject("approved_by", UUID.class), rs.getObject("paid_by", UUID.class),
                rs.getString("payment_reference"), rs.getObject("verified_by", UUID.class), rs.getString("decision_reason"),
                rs.getTimestamp("created_at").toInstant(), rs.getTimestamp("updated_at").toInstant(), rs.getLong("version"));
    }

    private static Money egp(long minor) {
        return new Money(minor, "EGP");
    }

    private static String text(String field, String value, int min, int max) {
        String v = value == null ? "" : value.strip();
        if (v.length() < min || v.length() > max) {
            throw invalid(field, "LENGTH_" + min + "_" + max);
        }
        return v;
    }

    private static ApiException invalid(String field, String code) {
        return new ApiException(ErrorCode.VALIDATION_FAILED, "invalid " + field, List.of(new FieldError(field, code)));
    }
}

package com.matbakhy.orders.internal;

import com.matbakhy.availability.api.SlotDirectory;
import com.matbakhy.availability.api.SlotDirectory.SlotStatus;
import com.matbakhy.catalog.api.MealCatalog;
import com.matbakhy.catalog.api.MealCatalog.PricedMeal;
import com.matbakhy.catalog.api.SellerDirectory;
import com.matbakhy.catalog.api.SellerDirectory.Seller;
import com.matbakhy.identity.api.AddressDirectory;
import com.matbakhy.identity.api.AddressDirectory.OwnedAddress;
import com.matbakhy.identity.api.CheckoutContactPolicy;
import com.matbakhy.orders.api.QuoteDirectory;
import com.matbakhy.orders.internal.CommercePolicies.Policy;
import com.matbakhy.shared.error.ApiException;
import com.matbakhy.shared.error.ApiException.FieldError;
import com.matbakhy.shared.error.ErrorCode;
import java.sql.Timestamp;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.OptionalLong;
import java.util.Set;
import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Authoritative quotes (BR-018..BR-021). The server derives every amount from current published meal revisions,
 * the zone/kitchen delivery fee and the active policy, in integer piastres; the request carries no amounts. A
 * quote is immutable, expires (default 5 minutes) and holds no stock.
 */
@Service
public class QuoteService implements QuoteDirectory {

    public enum Mode { PICKUP, DELIVERY }

    public record ItemRequest(UUID mealId, int quantity) {
    }

    public record QuoteRequest(List<ItemRequest> items, UUID slotId, Mode fulfillmentMode, UUID addressId, PaymentService.Method paymentMethod) {
    }

    public record Money(long amountMinor, String currency) {
    }

    public record QuoteLine(UUID mealId, int mealRevision, String title, int quantity, Money unitPrice, Money lineTotal) {
    }

    public record QuoteResponse(UUID quoteId, Instant expiresAt, UUID kitchenId, List<QuoteLine> items, Money subtotal, Money deliveryFee,
                                Money tax, Money total, String cancellationPolicyVersion, String termsVersion, Instant acceptanceDeadlinePreview,
                                List<String> warnings, PaymentService.Terms payment) {
    }

    static final int MAX_ITEMS = CommercePolicies.MAX_LINES_PER_ORDER;

    private final JdbcTemplate jdbc;
    private final CommercePolicies policies;
    private final MealCatalog meals;
    private final SellerDirectory sellers;
    private final SlotDirectory slots;
    private final AddressDirectory addresses;
    private final CheckoutContactPolicy contact;
    private final PaymentService payments;
    private final Clock clock;

    QuoteService(JdbcTemplate jdbc, CommercePolicies policies, MealCatalog meals, SellerDirectory sellers, SlotDirectory slots,
                 AddressDirectory addresses, CheckoutContactPolicy contact, PaymentService payments, Clock clock) {
        this.jdbc = jdbc;
        this.policies = policies;
        this.meals = meals;
        this.sellers = sellers;
        this.slots = slots;
        this.addresses = addresses;
        this.contact = contact;
        this.payments = payments;
        this.clock = clock;
    }

    private record Priced(PricedMeal meal, int quantity, long lineTotal) {
    }

    private record Terms(Seller seller, SlotStatus slot, List<Priced> lines, long subtotal, long deliveryFee, long tax, long total,
                         OwnedAddress address, Instant acceptBy) {
    }

    @Transactional
    public QuoteResponse create(UUID customerId, QuoteRequest in, boolean english) {
        contact.requireVerifiedContact(customerId);
        Policy policy = policies.active();
        if (in.items() == null || in.items().isEmpty() || in.items().size() > MAX_ITEMS) {
            throw invalid("items", "COUNT_1_TO_20");
        }
        Set<UUID> seen = new HashSet<>();
        for (ItemRequest item : in.items()) {
            if (item.mealId() == null || !seen.add(item.mealId())) {
                throw invalid("items", "DUPLICATE_OR_MISSING_MEAL");
            }
            if (item.quantity() < 1 || item.quantity() > policy.maxItemQuantity()) {
                throw invalid("items.quantity", "RANGE_1_TO_" + policy.maxItemQuantity());
            }
        }
        if (in.slotId() == null || in.fulfillmentMode() == null) {
            throw invalid(in.slotId() == null ? "slotId" : "fulfillmentMode", "REQUIRED");
        }
        Instant now = clock.instant();
        Terms t = terms(customerId, in.items(), in.slotId(), in.fulfillmentMode(), in.addressId(), policy, now);
        PaymentService.Method method = in.paymentMethod() == null ? PaymentService.Method.COD : in.paymentMethod();
        PaymentService.Terms pay = payments.terms(payments.profile(t.seller().kitchenId(), false), method, t.total());

        UUID id = UUID.randomUUID();
        Instant expires = now.plus(Duration.ofSeconds(policy.quoteTtlSeconds()));
        boolean delivery = in.fulfillmentMode() == Mode.DELIVERY;
        jdbc.update("""
                INSERT INTO quote (id, customer_id, kitchen_id, slot_id, fulfillment_mode, address_id, address_version, zone_id, policy_version,
                                   subtotal_minor, delivery_fee_minor, tax_minor, total_minor, accept_by_preview, expires_at, created_at,
                                   payment_method, deposit_bps, deposit_minor, recipient_method, recipient_identifier, recipient_name)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                id, customerId, t.seller().kitchenId(), in.slotId(), in.fulfillmentMode().name(), delivery ? t.address().id() : null,
                delivery ? t.address().version() : null, delivery ? t.address().zoneId() : null, policy.version(), t.subtotal(), t.deliveryFee(),
                t.tax(), t.total(), Timestamp.from(t.acceptBy()), Timestamp.from(expires), Timestamp.from(now), pay.method(), pay.depositBps(),
                pay.deposit().amountMinor(), pay.recipient() == null ? null : pay.recipient().method(),
                pay.recipient() == null ? null : pay.recipient().identifier(), pay.recipient() == null ? null : pay.recipient().name());
        List<QuoteLine> lines = new ArrayList<>();
        for (Priced p : t.lines()) {
            jdbc.update("""
                    INSERT INTO quote_item (quote_id, meal_id, meal_revision, quantity, unit_price_minor, line_total_minor)
                    VALUES (?, ?, ?, ?, ?, ?)""", id, p.meal().mealId(), p.meal().revision(), p.quantity(), p.meal().priceMinor(), p.lineTotal());
            String title = english && p.meal().titleEn() != null ? p.meal().titleEn() : p.meal().titleAr();
            lines.add(new QuoteLine(p.meal().mealId(), p.meal().revision(), title, p.quantity(), egp(p.meal().priceMinor()), egp(p.lineTotal())));
        }
        List<String> warnings = new ArrayList<>();
        if (policy.synthetic()) {
            warnings.add("SYNTHETIC_POLICY");
        }
        return new QuoteResponse(id, expires, t.seller().kitchenId(), lines, egp(t.subtotal()), egp(t.deliveryFee()), egp(t.tax()), egp(t.total()),
                policy.cancellationPolicyVersion(), policy.termsVersion(), t.acceptBy(), warnings, pay);
    }

    @Override
    @Transactional
    public ValidQuote requireValid(UUID customerId, UUID quoteId) {
        Map<String, Object> q = jdbc.queryForList("SELECT * FROM quote WHERE id = ? AND customer_id = ?", quoteId, customerId).stream()
                .findFirst().orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "quote not found"));
        // D13: lock the active policy and the rows that price this quote before reading them, so a concurrent price, fee or
        // policy change is serialized with the placement: an update that commits first is seen here (stale quote refused);
        // an update that comes later waits until this placement commits (the order keeps its validated price).
        jdbc.queryForList("SELECT version FROM commerce_policy WHERE status = 'ACTIVE' FOR SHARE", Integer.class);
        meals.lockPricing(jdbc.queryForList("SELECT meal_id FROM quote_item WHERE quote_id = ?", UUID.class, quoteId),
                (UUID) q.get("kitchen_id"), (UUID) q.get("zone_id"));
        Instant now = clock.instant();
        Instant expires = ((Timestamp) q.get("expires_at")).toInstant();
        if (!now.isBefore(expires)) {
            throw new ApiException(ErrorCode.QUOTE_EXPIRED, "quote expired", List.of(new FieldError("quoteId", "QUOTE_EXPIRED")));
        }
        contact.requireVerifiedContact(customerId);
        Policy policy = policies.active();
        if (policy.version() != (Integer) q.get("policy_version")) {
            throw changed(ErrorCode.PRICE_CHANGED, "POLICY_CHANGED");
        }
        List<QuotedItem> items = jdbc.query("""
                SELECT meal_id, meal_revision, quantity, unit_price_minor, line_total_minor FROM quote_item WHERE quote_id = ? ORDER BY meal_id""",
                (rs, n) -> new QuotedItem(rs.getObject(1, UUID.class), rs.getInt(2), rs.getInt(3), rs.getLong(4), rs.getLong(5)), quoteId);
        Mode mode = Mode.valueOf((String) q.get("fulfillment_mode"));
        UUID addressId = (UUID) q.get("address_id");
        Terms t = terms(customerId, items.stream().map(i -> new ItemRequest(i.mealId(), i.quantity())).toList(), (UUID) q.get("slot_id"), mode,
                addressId, policy, now);
        for (QuotedItem item : items) {
            Priced current = t.lines().stream().filter(p -> p.meal().mealId().equals(item.mealId())).findFirst().orElseThrow();
            if (current.meal().revision() != item.mealRevision() || current.meal().priceMinor() != item.unitPriceMinor()) {
                throw changed(ErrorCode.PRICE_CHANGED, "MEAL_CHANGED");
            }
        }
        if (addressId != null && (t.address().version() != (Long) q.get("address_version") || !t.address().zoneId().equals(q.get("zone_id")))) {
            throw changed(ErrorCode.STATE_CONFLICT, "ADDRESS_CHANGED");
        }
        if (t.deliveryFee() != (Long) q.get("delivery_fee_minor") || t.total() != (Long) q.get("total_minor")) {
            throw changed(ErrorCode.PRICE_CHANGED, "TOTAL_CHANGED");
        }
        // MB-051: the kitchen's payment terms are part of the quote; a change since quoting needs a new quote (D13 protocol).
        PaymentService.Terms pay;
        try {
            pay = payments.terms(payments.profile(t.seller().kitchenId(), true), PaymentService.Method.valueOf((String) q.get("payment_method")), t.total());
        } catch (ApiException e) {
            throw changed(ErrorCode.PRICE_CHANGED, "PAYMENT_CHANGED");
        }
        if (pay.depositBps() != (Integer) q.get("deposit_bps") || pay.deposit().amountMinor() != (Long) q.get("deposit_minor")
                || !java.util.Objects.equals(pay.recipient() == null ? null : pay.recipient().identifier(), q.get("recipient_identifier"))
                || !java.util.Objects.equals(pay.recipient() == null ? null : pay.recipient().method(), q.get("recipient_method"))
                || !java.util.Objects.equals(pay.recipient() == null ? null : pay.recipient().name(), q.get("recipient_name"))) {
            throw changed(ErrorCode.PRICE_CHANGED, "PAYMENT_CHANGED");
        }
        return new ValidQuote(quoteId, customerId, t.seller().kitchenId(), (UUID) q.get("slot_id"), mode.name(), addressId,
                (Long) q.get("address_version"), (UUID) q.get("zone_id"), policy.version(), t.subtotal(), t.deliveryFee(), t.tax(), t.total(),
                ((Timestamp) q.get("accept_by_preview")).toInstant(), expires, items, t.acceptBy(), policy.commissionRateBps(),
                policy.cancellationPolicyVersion(), policy.termsVersion(), pay.method(), pay.deposit().amountMinor(),
                pay.recipient() == null ? null : pay.recipient().method(), pay.recipient() == null ? null : pay.recipient().identifier(),
                pay.recipient() == null ? null : pay.recipient().name());
    }

    /** Recomputes the authoritative terms from current data; used for creation and revalidation. */
    private Terms terms(UUID customerId, List<ItemRequest> items, UUID slotId, Mode mode, UUID addressId, Policy policy, Instant now) {
        SlotStatus slot = slots.slot(slotId).orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "slot not found"));
        Seller seller = sellers.byKitchen(slot.kitchenId()).orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "kitchen not found"));
        if (!seller.canSell()) {
            throw new ApiException(ErrorCode.KITCHEN_UNAVAILABLE, "kitchen not selling");
        }
        if (!slot.orderableAt(now)) {
            throw new ApiException(ErrorCode.SLOT_CLOSED, "slot not orderable", List.of(new FieldError("slotId", "SLOT_CLOSED")));
        }
        Instant acceptBy = now.plus(Duration.ofMinutes(policy.acceptanceWindowMinutes()));
        if (slot.cutoffAt().isBefore(acceptBy)) {
            acceptBy = slot.cutoffAt();
        }
        if (Duration.between(now, acceptBy).compareTo(Duration.ofMinutes(policy.minAcceptanceMinutes())) < 0) {
            throw new ApiException(ErrorCode.SLOT_CLOSED, "too close to cutoff", List.of(new FieldError("slotId", "ACCEPTANCE_WINDOW_TOO_SHORT")));
        }
        List<Priced> lines = new ArrayList<>();
        long subtotal = 0;
        int portions = 0;
        for (ItemRequest item : items) {
            PricedMeal meal = meals.current(item.mealId()).filter(PricedMeal::published)
                    .orElseThrow(() -> new ApiException(ErrorCode.STOCK_CHANGED, "meal not available",
                            List.of(new FieldError("items", "MEAL_NOT_AVAILABLE"))));
            if (!meal.kitchenId().equals(slot.kitchenId())) {
                // One cook and one slot per basket (BR-018); never split or convert silently.
                throw invalid("items", "MIXED_KITCHENS_OR_SLOT");
            }
            if (!slot.mealAvailablePortions().containsKey(meal.mealId())) {
                throw invalid("items", "MEAL_NOT_OFFERED_IN_SLOT");
            }
            if (item.quantity() > slot.availableFor(meal.mealId())) {
                throw new ApiException(ErrorCode.STOCK_CHANGED, "not enough portions", List.of(new FieldError("items.quantity", "INSUFFICIENT_PORTIONS")));
            }
            long line = Math.multiplyExact(meal.priceMinor(), (long) item.quantity());
            subtotal = Math.addExact(subtotal, line);
            portions += item.quantity();
            lines.add(new Priced(meal, item.quantity(), line));
        }
        if (portions > slot.availablePortions()) {
            throw new ApiException(ErrorCode.STOCK_CHANGED, "not enough portions in slot", List.of(new FieldError("items.quantity", "INSUFFICIENT_PORTIONS")));
        }
        long fee = 0;
        OwnedAddress address = null;
        if (mode == Mode.PICKUP) {
            if (addressId != null) {
                throw invalid("addressId", "NOT_ALLOWED_FOR_PICKUP");
            }
            if (!seller.pickupEnabled()) {
                throw invalid("fulfillmentMode", "PICKUP_NOT_OFFERED");
            }
        } else {
            if (addressId == null) {
                throw invalid("addressId", "REQUIRED_FOR_DELIVERY");
            }
            address = addresses.owned(customerId, addressId).orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "address not found"));
            OptionalLong zoneFee = meals.deliveryFee(seller.kitchenId(), address.zoneId());
            if (zoneFee.isEmpty()) {
                throw invalid("addressId", "NOT_SERVICEABLE");
            }
            fee = zoneFee.getAsLong();
        }
        long base = Math.addExact(subtotal, fee);
        // Tax rounds half up to whole piastres (synthetic 0 bps until O04 decides tax treatment).
        long tax = Math.floorDiv(Math.addExact(Math.multiplyExact(base, (long) policy.taxRateBps()), 5_000L), 10_000L);
        long total = Math.addExact(base, tax);
        return new Terms(seller, slot, lines, subtotal, fee, tax, total, address, acceptBy);
    }

    private static Money egp(long minor) {
        return new Money(minor, "EGP");
    }

    private static ApiException changed(ErrorCode code, String reason) {
        return new ApiException(code, "quote no longer valid: " + reason, List.of(new FieldError("quoteId", reason)));
    }

    private static ApiException invalid(String field, String code) {
        return new ApiException(ErrorCode.VALIDATION_FAILED, "invalid quote " + field, List.of(new FieldError(field, code)));
    }
}

package com.matbakhy.catalog.internal;

import com.matbakhy.catalog.api.MealCatalog;
import java.util.Collection;
import java.util.Optional;
import java.util.OptionalLong;
import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;

@Component
class JdbcMealCatalog implements MealCatalog {

    private final JdbcTemplate jdbc;

    JdbcMealCatalog(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    @Override
    public Optional<PricedMeal> current(UUID mealId) {
        return jdbc.query("SELECT id, kitchen_id, status, moderation_state, revision, price_minor, title_ar, title_en FROM meal WHERE id = ?",
                (rs, n) -> new PricedMeal(rs.getObject("id", UUID.class), rs.getObject("kitchen_id", UUID.class),
                        "PUBLISHED".equals(rs.getString("status")) && "VISIBLE".equals(rs.getString("moderation_state")), rs.getInt("revision"), rs.getLong("price_minor"), rs.getString("title_ar"),
                        rs.getString("title_en")), mealId).stream().findFirst();
    }

    @Override
    public Optional<String> revisionSnapshot(UUID mealId, int revision) {
        return jdbc.query("SELECT snapshot::text FROM meal_revision WHERE meal_id = ? AND revision = ?", (rs, n) -> rs.getString(1), mealId,
                revision).stream().findFirst();
    }

    @Override
    public void lockPricing(Collection<UUID> mealIds, UUID kitchenId, UUID zoneIdOrNull) {
        jdbc.queryForList("SELECT id FROM meal WHERE id = ANY(?) ORDER BY id FOR SHARE", UUID.class, (Object) mealIds.toArray(UUID[]::new));
        if (zoneIdOrNull != null) {
            jdbc.queryForList("SELECT kitchen_id FROM kitchen_zone WHERE kitchen_id = ? AND zone_id = ? FOR SHARE", UUID.class, kitchenId, zoneIdOrNull);
            jdbc.queryForList("SELECT id FROM service_zone WHERE id = ? FOR SHARE", UUID.class, zoneIdOrNull);
        }
    }

    @Override
    public OptionalLong deliveryFee(UUID kitchenId, UUID zoneId) {
        Long fee = jdbc.query("""
                SELECT coalesce(kz.fee_override_minor, z.delivery_fee_minor) FROM kitchen_zone kz JOIN service_zone z ON z.id = kz.zone_id
                WHERE kz.kitchen_id = ? AND kz.zone_id = ? AND kz.delivery_enabled AND z.active""",
                rs -> rs.next() ? rs.getLong(1) : null, kitchenId, zoneId);
        return fee == null ? OptionalLong.empty() : OptionalLong.of(fee);
    }
}
package com.matbakhy.availability.internal;

import com.matbakhy.availability.api.SlotInventory;
import com.matbakhy.shared.error.ApiException;
import com.matbakhy.shared.error.ApiException.FieldError;
import com.matbakhy.shared.error.ErrorCode;
import java.sql.Timestamp;
import java.time.Clock;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

@Component
class JdbcSlotInventory implements SlotInventory {

    private final JdbcTemplate jdbc;
    private final Clock clock;

    JdbcSlotInventory(JdbcTemplate jdbc, Clock clock) {
        this.jdbc = jdbc;
        this.clock = clock;
    }

    private record MealSlotRow(UUID id, UUID mealId, int remaining) {
    }

    @Override
    @Transactional(propagation = Propagation.MANDATORY)
    public List<Reservation> reserve(UUID slotId, Map<UUID, Integer> quantityByMeal) {
        if (quantityByMeal.isEmpty() || quantityByMeal.values().stream().anyMatch(q -> q == null || q < 1)) {
            throw new IllegalArgumentException("reservation needs positive quantities");
        }
        // 1. Slot aggregate row first.
        Integer slotRemaining = jdbc.query("""
                SELECT max_portions - reserved - allocated - consumed FROM cook_slot
                WHERE id = ? AND state = 'OPEN' AND cutoff_at > ? FOR UPDATE""",
                rs -> rs.next() ? rs.getInt(1) : null, slotId, Timestamp.from(clock.instant()));
        if (slotRemaining == null) {
            throw new ApiException(ErrorCode.SLOT_CLOSED, "slot not orderable", List.of(new FieldError("slotId", "SLOT_CLOSED")));
        }
        // 2. Meal rows in id order.
        List<MealSlotRow> rows = jdbc.query("""
                SELECT id, meal_id, capacity - reserved - allocated - consumed FROM meal_slot
                WHERE cook_slot_id = ? AND meal_id = ANY (?) ORDER BY id FOR UPDATE""",
                (rs, n) -> new MealSlotRow(rs.getObject(1, UUID.class), rs.getObject(2, UUID.class), rs.getInt(3)),
                slotId, quantityByMeal.keySet().toArray(UUID[]::new));
        if (rows.size() != quantityByMeal.size()) {
            throw stock();
        }
        int total = 0;
        for (MealSlotRow row : rows) {
            int wanted = quantityByMeal.get(row.mealId());
            if (wanted > row.remaining()) {
                throw stock();
            }
            total += wanted;
        }
        if (total > slotRemaining) {
            throw stock();
        }
        List<Reservation> out = new ArrayList<>();
        for (MealSlotRow row : rows) {
            int wanted = quantityByMeal.get(row.mealId());
            jdbc.update("UPDATE meal_slot SET reserved = reserved + ?, version = version + 1 WHERE id = ?", wanted, row.id());
            out.add(new Reservation(row.id(), row.mealId(), wanted));
        }
        jdbc.update("UPDATE cook_slot SET reserved = reserved + ?, version = version + 1, updated_at = ? WHERE id = ?", total,
                Timestamp.from(clock.instant()), slotId);
        return out;
    }

    @Override
    @Transactional(propagation = Propagation.MANDATORY)
    public void move(UUID slotId, List<Line> lines, Stage from, Stage to) {
        if (lines.isEmpty() || from == to) {
            throw new IllegalArgumentException("nothing to move");
        }
        String f = column(from);
        String t = to == null ? null : column(to);
        int total = lines.stream().mapToInt(Line::quantity).sum();
        jdbc.query("SELECT id FROM cook_slot WHERE id = ? FOR UPDATE", rs -> null, slotId);
        List<UUID> ordered = lines.stream().map(Line::mealSlotId).sorted().toList();
        jdbc.query("SELECT id FROM meal_slot WHERE id = ANY (?) ORDER BY id FOR UPDATE", rs -> null, (Object) ordered.toArray(UUID[]::new));
        for (Line line : lines.stream().sorted(java.util.Comparator.comparing(Line::mealSlotId)).toList()) {
            int n = jdbc.update("UPDATE meal_slot SET " + f + " = " + f + " - ?" + (t == null ? "" : ", " + t + " = " + t + " + ?")
                    + ", version = version + 1 WHERE id = ? AND cook_slot_id = ? AND " + f + " >= ?",
                    t == null ? new Object[] {line.quantity(), line.mealSlotId(), slotId, line.quantity()}
                            : new Object[] {line.quantity(), line.quantity(), line.mealSlotId(), slotId, line.quantity()});
            if (n != 1) {
                throw new IllegalStateException("stock counter " + f + " would go negative for meal slot " + line.mealSlotId());
            }
        }
        int n = jdbc.update("UPDATE cook_slot SET " + f + " = " + f + " - ?" + (t == null ? "" : ", " + t + " = " + t + " + ?")
                + ", version = version + 1, updated_at = ? WHERE id = ? AND " + f + " >= ?",
                t == null ? new Object[] {total, Timestamp.from(clock.instant()), slotId, total}
                        : new Object[] {total, total, Timestamp.from(clock.instant()), slotId, total});
        if (n != 1) {
            throw new IllegalStateException("slot counter " + f + " would go negative for slot " + slotId);
        }
    }

    private static String column(Stage stage) {
        return switch (stage) {
            case RESERVED -> "reserved";
            case ALLOCATED -> "allocated";
            case CONSUMED -> "consumed";
        };
    }

    private static ApiException stock() {
        return new ApiException(ErrorCode.STOCK_CHANGED, "not enough portions", List.of(new FieldError("items", "INSUFFICIENT_PORTIONS")));
    }
}
